-- SOURCE sql/2026-11-24_sri_pacote03_historico_carteira.sql
-- Pacote 03: read-only history, without reactivating tasks or altering treatment records.
CREATE OR REPLACE FUNCTION private.sri_my_history_page(p_before bigint DEFAULT NULL,p_limit integer DEFAULT 200)
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('id',h.id::text,'action',h.action,'notes',h.notes,'created_at',h.created_at,'task_id',h.task_id,'protocol_number',t.protocol_number,'base_name',t.base_name,'area_name',t.area_name)
 FROM public.daily_operator_treatments h JOIN public.daily_operator_tasks t ON t.id=h.task_id
 WHERE h.actor_id=auth.uid() AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.role='operator' AND p.operational_status IN ('Ativo','Promovido'))
 AND (p_before IS NULL OR h.id<p_before)
 ORDER BY h.id DESC LIMIT greatest(1,least(coalesce(p_limit,200),200))
$$;
CREATE OR REPLACE FUNCTION public.sri_my_history_page(p_before bigint DEFAULT NULL,p_limit integer DEFAULT 200)
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT * FROM private.sri_my_history_page(p_before,p_limit); $$;
-- completed_in_tool is deliberately NOT treated as confirmed resolution in SIGO.
-- Historical rows require the caller's own recorded treatment, and are never reactivated.
CREATE OR REPLACE FUNCTION private.sri_my_daily_processed(p_before text DEFAULT NULL,p_limit integer DEFAULT 200)
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 WITH own_rows AS (
 SELECT DISTINCT ON(t.protocol_number) t.id,t.protocol_number,t.base_name,t.area_name,t.criticality,t.priority_reason,t.due_date,t.due_situation,t.sla_band,t.channel,t.shift_label,t.work_status,t.treatment_status,t.updated_at,t.active,t.operational_day
 FROM public.daily_operator_tasks t
 WHERE t.operator_user_id=auth.uid()
 AND t.operational_day=(now() AT TIME ZONE 'America/Fortaleza')::date
 AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.role='operator' AND p.operational_status IN ('Ativo','Promovido'))
 AND EXISTS(SELECT 1 FROM public.daily_operator_treatments h WHERE h.task_id=t.id AND h.actor_id=auth.uid())
 AND NOT EXISTS(SELECT 1 FROM public.daily_operator_tasks a WHERE a.protocol_number=t.protocol_number AND a.operational_day=t.operational_day AND a.active AND a.operator_user_id=auth.uid())
 ORDER BY t.protocol_number,t.updated_at DESC,t.id DESC
 ) SELECT to_jsonb(x) FROM own_rows x WHERE x.active=false AND x.work_status='completed_in_tool' AND (p_before IS NULL OR x.protocol_number>p_before)
 ORDER BY x.protocol_number LIMIT greatest(1,least(coalesce(p_limit,200),200))
$$;
CREATE OR REPLACE FUNCTION public.sri_my_daily_processed(p_before text DEFAULT NULL,p_limit integer DEFAULT 200)
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT * FROM private.sri_my_daily_processed(p_before,p_limit); $$;
REVOKE ALL ON FUNCTION private.sri_my_history_page(bigint,integer),public.sri_my_history_page(bigint,integer),private.sri_my_daily_processed(text,integer),public.sri_my_daily_processed(text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.sri_my_history_page(bigint,integer),public.sri_my_history_page(bigint,integer),private.sri_my_daily_processed(text,integer),public.sri_my_daily_processed(text,integer) TO authenticated;

-- SOURCE sql/2026-11-24_sri_pacote03_produtividade.sql
-- Consultas gerenciais somente leitura. SECURITY INVOKER mantém as políticas existentes.
-- Unidade: protocolo por operador/equipe/dia. Não somar operadores como se fossem protocolos globais.
CREATE OR REPLACE FUNCTION public.sri_p03_productivity(p_from date,p_to date)
RETURNS TABLE(operational_day date,team_name text,operator_name text,received bigint,treated bigint,active_stock bigint,finalized_in_tool bigint,untreated_active bigint)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 WITH permitted AS (
 SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.role IN ('admin','manager','supervisor')
 ), scoped AS (
 SELECT t.* FROM public.daily_operator_tasks t
 WHERE EXISTS(SELECT 1 FROM permitted)
 AND p_from IS NOT NULL AND p_to IS NOT NULL AND p_to>=p_from AND p_to-p_from<=31
 AND t.operational_day BETWEEN p_from AND p_to
 ), grouped AS (
 SELECT t.operational_day,t.team_id,t.operator_user_id,t.protocol_number,
 bool_or(t.active) AS is_active,
 bool_or(EXISTS(SELECT 1 FROM public.daily_operator_treatments h WHERE h.task_id=t.id AND h.actor_id=t.operator_user_id)) AS has_treatment,
 bool_or(t.active AND t.work_status='completed_in_tool') AS active_finalized,
 (array_agg(t.work_status ORDER BY t.updated_at DESC,t.id DESC))[1]='completed_in_tool' AS latest_finalized
 FROM scoped t GROUP BY t.operational_day,t.team_id,t.operator_user_id,t.protocol_number
 )
 SELECT g.operational_day,coalesce(tm.name,'Sem equipe identificada'),coalesce(p.full_name,'Operador não identificado'),
 count(*),count(*) FILTER(WHERE g.has_treatment),count(*) FILTER(WHERE g.is_active),
 count(*) FILTER(WHERE g.has_treatment AND (g.active_finalized OR (NOT g.is_active AND g.latest_finalized))),
 count(*) FILTER(WHERE g.is_active AND NOT g.has_treatment)
 FROM grouped g LEFT JOIN public.teams tm ON tm.id=g.team_id LEFT JOIN public.profiles p ON p.id=g.operator_user_id
 GROUP BY g.operational_day,g.team_id,g.operator_user_id,tm.name,p.full_name
 ORDER BY g.operational_day DESC,tm.name,p.full_name
$$;
REVOKE ALL ON FUNCTION public.sri_p03_productivity(date,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sri_p03_productivity(date,date) TO authenticated;

-- SOURCE sql/2026-11-24_sri_pacote03_protecao_incidentes.sql
-- Preserve autoria da tratativa entre apurações; não altera registros existentes.
CREATE OR REPLACE FUNCTION private.sri_carry_task_status()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE old_task public.daily_operator_tasks%rowtype;
BEGIN
 SELECT t.* INTO old_task FROM public.daily_operator_tasks t
 JOIN public.daily_result_snapshots s ON s.id=t.snapshot_id
 JOIN public.daily_result_snapshots n ON n.id=NEW.snapshot_id
 WHERE t.operational_day=NEW.operational_day AND t.shift_label=NEW.shift_label
 AND t.protocol_number=NEW.protocol_number AND t.snapshot_id<>NEW.snapshot_id
 AND s.team_id IS NOT DISTINCT FROM n.team_id AND t.active
 ORDER BY t.updated_at DESC,t.id DESC LIMIT 1;
 IF FOUND AND old_task.operator_user_id=NEW.operator_user_id THEN
 NEW.treatment_status:=old_task.treatment_status; NEW.work_status:=old_task.work_status;
 ELSIF FOUND AND old_task.work_status='completed_in_tool' THEN
 RAISE EXCEPTION 'Protocolo finalizado na ferramenta: revisão da supervisão necessária antes da redistribuição';
 END IF;
 RETURN NEW;
END $$;
-- Proíbe transferência direta de uma tarefa tratada, preservando vínculo com seus eventos.
CREATE OR REPLACE FUNCTION private.sri_p03_guard_transfer()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF OLD.operator_user_id IS DISTINCT FROM NEW.operator_user_id AND
 (OLD.work_status='completed_in_tool' OR EXISTS(SELECT 1 FROM public.daily_operator_treatments h WHERE h.task_id=OLD.id)) THEN
 RAISE EXCEPTION 'Protocolo com histórico de tratativa: revisão necessária antes de alterar o responsável';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sri_p03_guard_transfer ON public.daily_operator_tasks;
CREATE TRIGGER sri_p03_guard_transfer BEFORE UPDATE OF operator_user_id ON public.daily_operator_tasks FOR EACH ROW EXECUTE FUNCTION private.sri_p03_guard_transfer();
REVOKE ALL ON FUNCTION private.sri_p03_guard_transfer() FROM PUBLIC,anon,authenticated;
-- Incidentes técnicos: apenas identificador de evento e etapas predefinidas, sem texto sensível.
CREATE TABLE IF NOT EXISTS private.sri_p03_incidents (
 event_id bigint PRIMARY KEY REFERENCES private.sri_monitor_events(id) ON DELETE RESTRICT,
 stage text NOT NULL DEFAULT 'identified' CHECK(stage IN ('identified','analysis','correction','validation','resolved')),
 updated_by uuid NOT NULL, updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE private.sri_p03_incidents ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.sri_p03_incidents FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS private.sri_p03_incident_history (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,event_id bigint NOT NULL REFERENCES private.sri_p03_incidents(event_id),
 old_stage text,new_stage text NOT NULL,actor_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE private.sri_p03_incident_history ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.sri_p03_incident_history FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION private.sri_p03_incident_set(p_event bigint,p_expected text,p_stage text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE old_stage text; actor uuid:=auth.uid();
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=actor AND role='admin') THEN RAISE EXCEPTION 'Acesso exclusivo ao administrador'; END IF;
 IF NOT EXISTS(SELECT 1 FROM private.sri_monitor_events WHERE id=p_event AND severity IN ('ERROR','FATAL','WARN')) THEN RAISE EXCEPTION 'Evento indisponível'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-incident:'||p_event::text,0));
 SELECT stage INTO old_stage FROM private.sri_p03_incidents WHERE event_id=p_event;
 IF coalesce(old_stage,'identified') IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'Incidente alterado; atualize a consulta'; END IF;
 IF p_stage IS NULL OR NOT ((coalesce(old_stage,'identified'),p_stage) IN (('identified','analysis'),('analysis','correction'),('correction','validation'),('validation','resolved'),('validation','correction'),('resolved','analysis'))) THEN RAISE EXCEPTION 'Transição inválida'; END IF;
 INSERT INTO private.sri_p03_incidents(event_id,stage,updated_by) VALUES(p_event,p_stage,actor)
 ON CONFLICT(event_id) DO UPDATE SET stage=EXCLUDED.stage,updated_by=actor,updated_at=now();
 INSERT INTO private.sri_p03_incident_history(event_id,old_stage,new_stage,actor_id) VALUES(p_event,coalesce(old_stage,'identified'),p_stage,actor);
END $$;
CREATE OR REPLACE FUNCTION public.sri_p03_incident_set(p_event bigint,p_expected text,p_stage text)
RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT private.sri_p03_incident_set(p_event,p_expected,p_stage); $$;
CREATE OR REPLACE FUNCTION private.sri_p03_incident_list()
RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role='admin') THEN RAISE EXCEPTION 'Acesso exclusivo ao administrador'; END IF;
 RETURN QUERY SELECT jsonb_build_object('event_id',i.event_id::text,'stage',i.stage,'updated_at',i.updated_at) FROM private.sri_p03_incidents i ORDER BY i.updated_at DESC LIMIT 1000;
END $$;
CREATE OR REPLACE FUNCTION public.sri_p03_incident_list()
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT * FROM private.sri_p03_incident_list(); $$;
REVOKE ALL ON FUNCTION private.sri_p03_incident_set(bigint,text,text),public.sri_p03_incident_set(bigint,text,text),private.sri_p03_incident_list(),public.sri_p03_incident_list() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.sri_p03_incident_set(bigint,text,text),public.sri_p03_incident_set(bigint,text,text),private.sri_p03_incident_list(),public.sri_p03_incident_list() TO authenticated;

-- SOURCE sql/2026-11-24_sri_criticos_persistencia_status.sql
-- PACOTE 03 / P0 - sem modificação retroativa das tratativas
-- Executar apenas em janela controlada DEPOIS de 2026-11-24_sri_pacote03_protecao_incidentes.sql.

CREATE OR REPLACE FUNCTION private.sri_p03_status_sigo(v text) RETURNS integer LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT CASE
  WHEN v IN ('E-MAIL','LIGAÇÃO','ASCSAC','ACEITOU','OUTROS','MÍDIAS NE','CARTA AR') THEN 3
  WHEN v IN ('RECUSOU','ASSOCIADO','OUVIDORIA') THEN 2
  WHEN v IN ('DÚVIDA','PENDENTE') THEN 0
  WHEN v='FILIAL' THEN 10 ELSE NULL END
$$;
CREATE OR REPLACE FUNCTION private.sri_p03_status_work(v text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT CASE
  WHEN v IN ('E-MAIL','LIGAÇÃO','ASCSAC','ACEITOU','OUTROS','MÍDIAS NE','CARTA AR') THEN 'completed_in_tool'
  WHEN v IN ('RECUSOU','ASSOCIADO','FILIAL') THEN 'awaiting'
  WHEN v IN ('DÚVIDA','PENDENTE') THEN 'pending'
  WHEN v='OUVIDORIA' THEN 'in_progress'
  ELSE NULL END
$$;
REVOKE ALL ON FUNCTION private.sri_p03_status_sigo(text),private.sri_p03_status_work(text) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.record_daily_operator_treatment(p_task uuid, p_action text, p_notes text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_task public.daily_operator_tasks%rowtype;
  v_day date;
  v_id bigint;
  v_allowed boolean:=false;
  v_note text;
  v_work_status text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sessão obrigatória';
  END IF;

  SELECT operational_day INTO v_day FROM public.daily_operator_tasks WHERE id=p_task;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tarefa indisponível ou inativa'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||v_day::text,0));
  SELECT * INTO v_task
    FROM public.daily_operator_tasks
   WHERE id=p_task FOR UPDATE;
  IF NOT FOUND OR NOT v_task.active THEN
    RAISE EXCEPTION 'Tarefa indisponível ou inativa';
  END IF;

  -- Mantém autorização por responsável, equipe, vínculo e situação operacional.
  IF v_task.operator_user_id=auth.uid() THEN
    SELECT EXISTS(
      SELECT 1 FROM public.profiles p
      WHERE p.id=auth.uid() AND p.role='operator'
        AND p.operational_status IN ('Ativo','Promovido')
        AND (v_task.team_id IS NULL OR EXISTS (
          SELECT 1 FROM public.team_memberships tm
          JOIN public.operator_links ol
            ON ol.user_id=tm.user_id AND ol.team_id=tm.team_id
          WHERE tm.user_id=p.id AND tm.team_id=v_task.team_id
        ))
    ) INTO v_allowed;
  END IF;
  IF NOT (v_allowed OR private.is_manager() OR
          (v_task.team_id IS NOT NULL AND private.is_supervisor_of(v_task.team_id))) THEN
    RAISE EXCEPTION 'Acesso negado à tarefa';
  END IF;

  -- Compatibilidade temporaria: telas antigas podem enviar os quatro valores tecnicos.
  IF p_action IS NULL OR p_action NOT IN (
    'E-MAIL','LIGAÇÃO','ASCSAC','RECUSOU','ACEITOU','ASSOCIADO',
    'OUTROS','FILIAL','DÚVIDA','OUVIDORIA','PENDENTE','MÍDIAS NE','CARTA AR',
    'note','in_progress','awaiting','completed_in_tool'
  ) THEN
    RAISE EXCEPTION 'Selecione um dos 13 status de tratativa';
  END IF;
  v_note:=btrim(COALESCE(p_notes,''));
  IF length(v_note)>1500 THEN
    RAISE EXCEPTION 'Justificativa deve ter até 1.500 caracteres';
  END IF;

  -- Work_status mantém o contrato das métricas existentes.
  -- Tratativa original é independente do status do SIGO.
  v_work_status:=CASE
    WHEN p_action='note' THEN v_task.work_status
    WHEN p_action IN ('in_progress','awaiting','completed_in_tool') THEN p_action
    ELSE private.sri_p03_status_work(p_action)
  END;

  INSERT INTO public.daily_operator_treatments(task_id,actor_id,action,notes)
    VALUES(v_task.id,auth.uid(),p_action,v_note)
    RETURNING id INTO v_id;

  UPDATE public.daily_operator_tasks
     SET treatment_status=CASE
           WHEN p_action IN ('note','in_progress','awaiting','completed_in_tool')
             THEN v_task.treatment_status
           ELSE p_action END,
         work_status=v_work_status,
         updated_at=now()
   WHERE id=v_task.id;

  INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
  VALUES (
    auth.uid(),'DAY_TASK_TREATMENT','daily_operator_task',v_task.id::text,
    jsonb_build_object(
      'team_id',v_task.team_id,
      'previous_treatment_status',v_task.treatment_status,
      'treatment_status',p_action,
      'work_status',v_work_status,
      'sigo_reference',private.sri_p03_status_sigo(p_action),
      'treatment_id',v_id
    )
  );
  RETURN v_id;
END;
$function$
;


CREATE OR REPLACE FUNCTION private.sri_carry_task_status()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE old_task public.daily_operator_tasks%rowtype;
BEGIN
 SELECT t.* INTO old_task FROM public.daily_operator_tasks t
 JOIN public.daily_result_snapshots s ON s.id=t.snapshot_id
 JOIN public.daily_result_snapshots n ON n.id=NEW.snapshot_id
 WHERE t.operational_day=NEW.operational_day AND t.shift_label=NEW.shift_label
 AND t.protocol_number=NEW.protocol_number AND t.snapshot_id<>NEW.snapshot_id
 AND s.team_id IS NOT DISTINCT FROM n.team_id AND t.active
 ORDER BY t.updated_at DESC,t.id DESC LIMIT 1;
 IF FOUND THEN
  IF old_task.operator_user_id=NEW.operator_user_id THEN
   NEW.treatment_status:=old_task.treatment_status;
   NEW.work_status:=old_task.work_status;
  ELSIF old_task.work_status<>'pending' OR EXISTS(
   SELECT 1 FROM public.daily_operator_treatments h WHERE h.task_id=old_task.id) THEN
   RAISE EXCEPTION 'Protocolo tratado por outro operador: conciliar responsável antes de redistribuir';
  END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION private.sri_p03_guard_transfer()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF OLD.operator_user_id IS DISTINCT FROM NEW.operator_user_id
 AND (OLD.work_status<>'pending' OR EXISTS(
  SELECT 1 FROM public.daily_operator_treatments h WHERE h.task_id=OLD.id)) THEN
  RAISE EXCEPTION 'Protocolo tratado: revisão da supervisão necessária antes de transferir';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sri_p03_guard_transfer ON public.daily_operator_tasks;
CREATE TRIGGER sri_p03_guard_transfer BEFORE UPDATE OF operator_user_id
 ON public.daily_operator_tasks FOR EACH ROW EXECUTE FUNCTION private.sri_p03_guard_transfer();
REVOKE ALL ON FUNCTION private.sri_p03_guard_transfer() FROM PUBLIC,anon,authenticated;


-- Conciliação automática APENAS da mesma data, turno e origem da apuração; sem reviver inativos antigos.
CREATE OR REPLACE FUNCTION private.sri_p03_preserve_open_tasks(
 p_snapshot uuid,p_day date,p_shift text,p_scope_team uuid,p_revision bigint)
RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE v_count integer:=0;
BEGIN
 IF EXISTS(
  SELECT 1 FROM public.daily_operator_tasks old
  JOIN public.daily_result_snapshots os ON os.id=old.snapshot_id
  JOIN public.daily_operator_tasks fresh ON fresh.snapshot_id=p_snapshot
       AND fresh.protocol_number=old.protocol_number
  WHERE old.snapshot_id<>p_snapshot AND old.active
   AND old.operational_day=p_day AND old.shift_label=p_shift
   AND os.team_id IS NOT DISTINCT FROM p_scope_team
   AND old.operator_user_id IS DISTINCT FROM fresh.operator_user_id
   AND (old.work_status<>'pending' OR EXISTS(
    SELECT 1 FROM public.daily_operator_treatments h WHERE h.task_id=old.id))
 ) THEN
  RAISE EXCEPTION 'Distribuição conflita com tratativa prévia: revisão manual obrigatória';
 END IF;
 WITH prior AS (
  SELECT DISTINCT ON(old.protocol_number) old.*
  FROM public.daily_operator_tasks old
  JOIN public.daily_result_snapshots os ON os.id=old.snapshot_id
  WHERE old.snapshot_id<>p_snapshot AND old.active
   AND old.operational_day=p_day AND old.shift_label=p_shift
   AND os.team_id IS NOT DISTINCT FROM p_scope_team
   AND old.work_status<>'completed_in_tool'
   AND private.sri_p03_status_sigo(old.treatment_status) IS DISTINCT FROM 3
   AND NOT EXISTS (SELECT 1 FROM public.daily_operator_tasks fresh
     WHERE fresh.snapshot_id=p_snapshot AND fresh.protocol_number=old.protocol_number)
  ORDER BY old.protocol_number,old.updated_at DESC,old.id DESC
 )
 INSERT INTO public.daily_operator_tasks
  (snapshot_id,team_id,operational_day,shift_label,protocol_number,operator_user_id,
   criticality,due_situation,sla_band,channel,source_status,work_status,
   treatment_status,active,distribution_revision,priority_reason,due_date,base_name,area_name)
 SELECT p_snapshot,old.team_id,p_day,p_shift,old.protocol_number,old.operator_user_id,
  old.criticality,old.due_situation,old.sla_band,old.channel,old.source_status,
  old.work_status,old.treatment_status,true,p_revision,old.priority_reason,old.due_date,
  old.base_name,old.area_name
 FROM prior old JOIN public.profiles op ON op.id=old.operator_user_id
  AND op.role='operator' AND op.operational_status IN ('Ativo','Promovido')
 ON CONFLICT(snapshot_id,protocol_number) DO NOTHING;
 GET DIAGNOSTICS v_count=ROW_COUNT;
 UPDATE public.daily_operator_tasks t SET distribution_revision=p_revision,updated_at=now()
 WHERE t.snapshot_id=p_snapshot AND t.active AND t.distribution_revision<>p_revision
   AND t.work_status<>'completed_in_tool'
   AND private.sri_p03_status_sigo(t.treatment_status) IS DISTINCT FROM 3;
 IF v_count>0 THEN
  INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
  VALUES(auth.uid(),'P03_UNFINISHED_CARRIED','daily_result',p_snapshot::text,
    jsonb_build_object('day',p_day,'shift',p_shift,'carried',v_count,'revision',p_revision));
 END IF;
 RETURN v_count;
END $$;
REVOKE ALL ON FUNCTION private.sri_p03_preserve_open_tasks(uuid,date,text,uuid,bigint) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.publish_daily_operator_tasks(p_snapshot uuid, p_revision bigint, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_team uuid; v_day date; v_shift text; v_state jsonb; v_revision bigint;
  v_assignments jsonb; v_roster jsonb; v_archive jsonb;
  v_id text; v_opid text; v_name text; v_user uuid;
  v_entry record; v_detail jsonb; v_criticality text; v_latest uuid; v_lock_day date;
  v_published integer:=0; v_unlinked integer:=0; v_changed integer:=0;
  v_unlinked_names jsonb:='[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão obrigatória'; END IF;
  SELECT operational_day INTO v_lock_day FROM public.daily_result_snapshots WHERE id=p_snapshot;
  IF NOT FOUND THEN RAISE EXCEPTION 'Apuração ou distribuição inexistente'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||v_lock_day::text,0));
  IF p_details IS NULL OR jsonb_typeof(p_details)<>'object' THEN
    RAISE EXCEPTION 'Detalhes inválidos';
  END IF;
  SELECT s.team_id,s.operational_day,s.shift_label,d.state,d.revision
  INTO v_team,v_day,v_shift,v_state,v_revision
  FROM public.daily_result_snapshots s
  JOIN public.daily_result_distributions d ON d.snapshot_id=s.id
  WHERE s.id=p_snapshot FOR SHARE OF d;
  IF NOT FOUND THEN RAISE EXCEPTION 'Apuração ou distribuição inexistente'; END IF;
  IF NOT (private.is_manager() OR private.is_supervisor_of(v_team)) THEN
    RAISE EXCEPTION 'Somente gestão/supervisão da equipe pode publicar'; END IF;
  IF v_revision<>p_revision THEN
    RAISE EXCEPTION 'A distribuição mudou em outro navegador. Recarregue antes de publicar'; END IF;
  -- Não permita que apurações históricas desativem tarefas da apuração mais recente.
  SELECT s.id INTO v_latest FROM public.daily_result_snapshots s
  WHERE s.team_id=v_team AND s.operational_day=v_day AND s.shift_label=v_shift
  ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
  IF v_latest IS DISTINCT FROM p_snapshot THEN
    RAISE EXCEPTION 'Apuração anterior: recupere a rodada mais recente antes de publicar carteiras';
  END IF;
  IF EXISTS(SELECT 1 FROM public.sri_result_shift_closures c WHERE c.team_id=v_team AND c.operational_day=v_day AND c.shift_label=v_shift AND c.status='closed')
     OR EXISTS(SELECT 1 FROM public.sri_result_day_closures d WHERE d.operational_day=v_day AND d.status IN ('closed','closed_with_pending')) THEN
    RAISE EXCEPTION 'Turno ou dia encerrado: solicite reabertura autorizada antes de publicar';
  END IF;
  v_assignments:=COALESCE(v_state->'assignments','{}'::jsonb);
  v_roster:=COALESCE(v_state->'roster','[]'::jsonb);
  v_archive:=COALESCE(v_state->'archivedRoster','[]'::jsonb);
  IF jsonb_typeof(v_assignments)<>'object' OR jsonb_typeof(v_roster)<>'array'
     OR jsonb_typeof(v_archive)<>'array' THEN
    RAISE EXCEPTION 'Estrutura da distribuição incompatível';
  END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(v_assignments))>15000 THEN
    RAISE EXCEPTION 'Distribuição excede 15 mil atribuições por rodada';
  END IF;
  FOR v_entry IN SELECT key,value FROM jsonb_each(v_assignments) LOOP
    v_id:=btrim(v_entry.key);
    v_opid:=v_entry.value->>'opId';
    IF v_id IS NULL OR length(v_id)<1 OR length(v_id)>100 OR v_opid IS NULL THEN CONTINUE; END IF;
    SELECT item->>'name' INTO v_name FROM (
      SELECT item FROM jsonb_array_elements(v_roster) AS z(item)
      UNION ALL
      SELECT item FROM jsonb_array_elements(v_archive) AS z(item)
    ) list WHERE list.item->>'id'=v_opid LIMIT 1;
    v_user:=NULL;
    -- Para novos cadastros o ID da conta é o identificador da distribuição.
    -- A equipe e a situação são confirmadas NO BANCO, sem confiar no navegador.
    IF v_opid ~ '^acct:[0-9a-fA-F-]{36}$' THEN
      SELECT p.id INTO v_user FROM public.profiles p
      JOIN public.team_memberships tm ON tm.user_id=p.id AND tm.team_id=v_team
      JOIN public.operator_links link ON link.user_id=p.id AND link.team_id=v_team
      WHERE p.id=substring(v_opid from 6)::uuid AND p.role='operator'
        AND p.operational_status IN ('Ativo','Promovido')
      LIMIT 1;
    ELSIF v_name IS NOT NULL THEN
      -- Compatibilidade de históricos: somente vínculos já conferidos manualmente.
      SELECT link.user_id INTO v_user FROM public.operator_links link
      JOIN public.profiles p ON p.id=link.user_id AND p.role='operator'
      JOIN public.team_memberships tm ON tm.user_id=link.user_id AND tm.team_id=link.team_id
      WHERE link.team_id=v_team AND p.operational_status IN ('Ativo','Promovido')
        AND lower(btrim(link.operator_name))=lower(btrim(v_name))
      LIMIT 1;
    END IF;
    IF v_user IS NULL THEN
      v_unlinked:=v_unlinked+1;
      IF jsonb_array_length(v_unlinked_names)<15 THEN
         v_unlinked_names:=v_unlinked_names || jsonb_build_array(COALESCE(v_name,'Operador não identificado'));
      END IF;
      CONTINUE;
    END IF;
    v_detail:=COALESCE(p_details->v_id,'{}'::jsonb);
    IF jsonb_typeof(v_detail)<>'object' THEN v_detail:='{}'::jsonb; END IF;
    v_criticality:=COALESCE(NULLIF(v_state->'criticities'->v_id->>'value',''),NULLIF(v_detail->>'criticality',''));
    INSERT INTO public.daily_operator_tasks
    (snapshot_id,team_id,operational_day,shift_label,protocol_number,operator_user_id,
     criticality,due_situation,sla_band,channel,source_status,distribution_revision,active,priority_reason,due_date,base_name,area_name)
    VALUES
    (p_snapshot,v_team,v_day,v_shift,v_id,v_user,
     left(v_criticality,80),left(v_detail->>'situation',80),left(v_detail->>'sla',50),
     left(v_detail->>'channel',80),left(v_detail->>'status',80),
     v_revision,true,private.sri_priority_reason(v_detail->>'priority_reason'),private.sri_priority_date(v_detail->>'due_date'),left(v_detail->>'base',120),left(v_detail->>'area',120))
    ON CONFLICT(snapshot_id,protocol_number) DO UPDATE SET
      operator_user_id=EXCLUDED.operator_user_id,
      criticality=EXCLUDED.criticality,priority_reason=EXCLUDED.priority_reason,due_date=EXCLUDED.due_date,
      due_situation=EXCLUDED.due_situation,
      sla_band=EXCLUDED.sla_band,
      channel=EXCLUDED.channel,
      source_status=COALESCE(EXCLUDED.source_status,daily_operator_tasks.source_status),base_name=COALESCE(EXCLUDED.base_name,daily_operator_tasks.base_name),area_name=COALESCE(EXCLUDED.area_name,daily_operator_tasks.area_name),
      active=true,distribution_revision=EXCLUDED.distribution_revision,updated_at=now(),
      work_status=public.daily_operator_tasks.work_status;
    v_published:=v_published+1;
  END LOOP;
  PERFORM private.sri_p03_preserve_open_tasks(p_snapshot,v_day,v_shift,v_team,v_revision);
  -- Desativa atribuições removidas, sem excluir histórico. Também invalida rodadas anteriores do mesmo turno.
  UPDATE public.daily_operator_tasks t SET active=false,updated_at=now()
  WHERE t.snapshot_id=p_snapshot AND t.active AND t.distribution_revision<>v_revision;
  GET DIAGNOSTICS v_changed=ROW_COUNT;
  UPDATE public.daily_operator_tasks t SET active=false,updated_at=now()
  WHERE t.snapshot_id<>p_snapshot AND t.team_id=v_team AND t.operational_day=v_day
    AND t.shift_label=v_shift AND t.active;
  INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
  VALUES(auth.uid(),'DAY_OPERATOR_TASKS_PUBLISHED','daily_result',p_snapshot::text,
         jsonb_build_object('revision',v_revision,'published',v_published,'unlinked',v_unlinked,'deactivated',v_changed));
  RETURN jsonb_build_object('published',v_published,'unlinked',v_unlinked,
                            'unlinked_names',v_unlinked_names,'revision',v_revision);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.publish_general_operator_tasks(p_snapshot uuid, p_revision bigint, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_day date;v_shift text;v_state jsonb;v_revision bigint;v_latest uuid;
 v_assignment record;v_protocol text;v_opid text;v_user uuid;v_team uuid;
 v_role text;v_status text;v_supervisor uuid;v_num_teams integer;
 v_criticality text;v_detail jsonb;v_published integer:=0;v_changed integer:=0;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão obrigatória'; END IF;
 IF NOT (private.is_manager() OR EXISTS(SELECT 1 FROM public.profiles p
  WHERE p.id=auth.uid() AND p.role='supervisor')) THEN
  RAISE EXCEPTION 'Publicação restrita à gestão e supervisão'; END IF;
 IF p_details IS NULL OR jsonb_typeof(p_details)<>'object' THEN
  RAISE EXCEPTION 'Detalhes inválidos';END IF;
 SELECT s.operational_day,s.shift_label,d.state,d.revision
 INTO v_day,v_shift,v_state,v_revision
 FROM public.daily_result_snapshots s JOIN public.daily_result_distributions d ON d.snapshot_id=s.id
 WHERE s.id=p_snapshot AND s.team_id IS NULL FOR SHARE OF d;
 IF NOT FOUND THEN RAISE EXCEPTION 'Resultado geral não publicado';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||v_day::text,0));
 IF v_revision IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'A distribuição mudou: recarregue o resultado';END IF;
 IF EXISTS(SELECT 1 FROM public.sri_general_day_closures c WHERE c.operational_day=v_day)
  OR EXISTS(SELECT 1 FROM public.sri_result_day_closures c WHERE c.operational_day=v_day
   AND c.status IN('closed','closed_with_pending')) THEN
  RAISE EXCEPTION 'Dia operacional encerrado: distribuição bloqueada';END IF;
 SELECT s.id INTO v_latest FROM public.daily_result_snapshots s
 WHERE s.team_id IS NULL AND s.operational_day=v_day AND s.shift_label=v_shift
 ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
 IF v_latest IS DISTINCT FROM p_snapshot THEN
  RAISE EXCEPTION 'Apuração geral anterior: recupere a importação mais recente';END IF;
 IF jsonb_typeof(v_state->'assignments') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'Estrutura da distribuição inválida';END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(v_state->'assignments'))>15000 THEN
  RAISE EXCEPTION 'Limite de 15 mil atribuições por rodada excedido';END IF;
 -- Todos os vínculos são validados ANTES de efetuar qualquer INSERT.
 FOR v_assignment IN SELECT key,value FROM jsonb_each(v_state->'assignments') LOOP
  v_protocol:=btrim(v_assignment.key);v_opid:=v_assignment.value->>'opId';
  IF length(v_protocol) NOT BETWEEN 1 AND 100 OR v_opid IS NULL
    OR v_opid !~ '^acct:[0-9a-fA-F-]{36}$' THEN
    RAISE EXCEPTION 'Operador não cadastrado em protocolo: %',left(v_protocol,100);
  END IF;
  v_user:=substring(v_opid FROM 6)::uuid;
  SELECT p.role,p.operational_status,p.supervisor_id INTO v_role,v_status,v_supervisor
  FROM public.profiles p WHERE p.id=v_user;
  IF NOT FOUND OR v_role<>'operator' OR v_status NOT IN('Ativo','Promovido') THEN
    RAISE EXCEPTION 'Operador inativo ou inválido para o protocolo %',v_protocol; END IF;
  SELECT count(*),(array_agg(tm.team_id ORDER BY tm.team_id))[1] INTO v_num_teams,v_team
  FROM public.team_memberships tm JOIN public.teams t ON t.id=tm.team_id AND t.active
  WHERE tm.user_id=v_user;
  IF v_num_teams>1 THEN
    RAISE EXCEPTION 'Operador possui mais de uma equipe ativa; revise vínculo antes de distribuir'; END IF;
  IF EXISTS(SELECT 1 FROM public.daily_operator_tasks t WHERE t.operator_user_id=v_user AND t.active
    AND t.team_id IS DISTINCT FROM v_team AND private.sri_task_blocks_transfer(t.operational_day,t.team_id,t.shift_label)) THEN
    RAISE EXCEPTION 'Operador possui vínculo conflitante; a gestão deve revisar antes de distribuir'; END IF;
  IF NOT (private.is_manager() OR v_supervisor=(SELECT auth.uid())
   OR (v_team IS NOT NULL AND private.is_supervisor_of(v_team))) THEN
    RAISE EXCEPTION 'Operador fora da equipe sob responsabilidade da supervisão';END IF;
 END LOOP;
 FOR v_assignment IN SELECT key,value FROM jsonb_each(v_state->'assignments') LOOP
  v_protocol:=btrim(v_assignment.key);
  v_user:=substring(v_assignment.value->>'opId' FROM 6)::uuid;
  SELECT (array_agg(tm.team_id ORDER BY tm.team_id))[1] INTO v_team
  FROM public.team_memberships tm JOIN public.teams t ON t.id=tm.team_id AND t.active
  WHERE tm.user_id=v_user;
  IF v_team IS NOT NULL THEN
   -- Compatibilidade com FK de vínculo existente; só em equipe explicitamente cadastrada.
   INSERT INTO public.operator_links(team_id,user_id,operator_name,linked_by)
   VALUES(v_team,v_user,'USER:'||v_user::text,(SELECT auth.uid()))
   ON CONFLICT (team_id,user_id) DO NOTHING;
  END IF;
  v_detail:=COALESCE(p_details->v_protocol,'{}'::jsonb);
  IF jsonb_typeof(v_detail)<>'object' THEN v_detail:='{}'::jsonb;END IF;
  v_criticality:=COALESCE(NULLIF(v_state->'criticities'->v_protocol->>'value',''),
     NULLIF(v_detail->>'criticality',''));
  INSERT INTO public.daily_operator_tasks
  (snapshot_id,team_id,operational_day,shift_label,protocol_number,operator_user_id,
   criticality,due_situation,sla_band,channel,source_status,distribution_revision,active,priority_reason,due_date,base_name,area_name)
  VALUES(p_snapshot,v_team,v_day,v_shift,v_protocol,v_user,
   left(v_criticality,80),left(v_detail->>'situation',80),left(v_detail->>'sla',50),
   left(v_detail->>'channel',80),
   left(v_detail->>'status',80),v_revision,true,private.sri_priority_reason(v_detail->>'priority_reason'),private.sri_priority_date(v_detail->>'due_date'),left(v_detail->>'base',120),left(v_detail->>'area',120))
  ON CONFLICT(snapshot_id,protocol_number) DO UPDATE SET
   operator_user_id=EXCLUDED.operator_user_id,team_id=EXCLUDED.team_id,
   criticality=EXCLUDED.criticality,priority_reason=EXCLUDED.priority_reason,due_date=EXCLUDED.due_date,due_situation=EXCLUDED.due_situation,
   sla_band=EXCLUDED.sla_band,channel=EXCLUDED.channel,
   source_status=COALESCE(EXCLUDED.source_status,daily_operator_tasks.source_status),base_name=COALESCE(EXCLUDED.base_name,daily_operator_tasks.base_name),area_name=COALESCE(EXCLUDED.area_name,daily_operator_tasks.area_name),
   active=true,distribution_revision=EXCLUDED.distribution_revision,updated_at=now(),
   work_status=public.daily_operator_tasks.work_status;
  v_published:=v_published+1;
 END LOOP;
 PERFORM private.sri_p03_preserve_open_tasks(p_snapshot,v_day,v_shift,NULL::uuid,v_revision);
 UPDATE public.daily_operator_tasks t SET active=false,updated_at=now()
 WHERE t.snapshot_id=p_snapshot AND t.active AND t.distribution_revision<>v_revision;
 GET DIAGNOSTICS v_changed=ROW_COUNT;
 -- Versionamento: a nova rodada desativa a anterior SOMENTE deste turno/apuração geral.
 UPDATE public.daily_operator_tasks t SET active=false,updated_at=now()
 WHERE t.snapshot_id<>p_snapshot AND t.operational_day=v_day AND t.shift_label=v_shift
  AND t.active AND EXISTS(SELECT 1 FROM public.daily_result_snapshots s
    WHERE s.id=t.snapshot_id AND s.team_id IS NULL);
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES((SELECT auth.uid()),'GENERAL_OPERATOR_TASKS_PUBLISHED','daily_result',p_snapshot::text,
  jsonb_build_object('revision',v_revision,'published',v_published,'prior_revision_removed',v_changed));
 RETURN jsonb_build_object('published',v_published,'unlinked',0,'revision',v_revision);
END;
$function$
;


CREATE OR REPLACE FUNCTION private.sri_p03_my_unresolved()
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 WITH latest AS (
  SELECT DISTINCT ON(t.protocol_number)
   t.protocol_number,t.operator_user_id,t.work_status,t.treatment_status,t.operational_day,
   t.shift_label,t.updated_at,t.active,t.criticality,t.due_date,t.base_name,t.area_name
  FROM public.daily_operator_tasks t JOIN public.daily_result_snapshots s ON s.id=t.snapshot_id
  WHERE t.operational_day<=(now() AT TIME ZONE 'America/Sao_Paulo')::date
  ORDER BY t.protocol_number,t.operational_day DESC,s.created_at DESC,t.active DESC,
   t.updated_at DESC,t.id DESC
 )
 SELECT jsonb_build_object('protocol_number',t.protocol_number,'last_day',t.operational_day,
  'shift_label',t.shift_label,'work_status',t.work_status,
  'treatment_status',t.treatment_status,'updated_at',t.updated_at,
  'sigo_reference',private.sri_p03_status_sigo(t.treatment_status),
  'criticality',t.criticality,'due_date',t.due_date,
  'base_name',t.base_name,'area_name',t.area_name,
  'requires_reconciliation',true)
 FROM latest t
 WHERE t.operator_user_id=auth.uid()
 AND t.work_status<>'completed_in_tool'
 AND (NOT t.active OR t.operational_day<(now() AT TIME ZONE 'America/Sao_Paulo')::date)
 AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid()
  AND p.role='operator' AND p.operational_status IN ('Ativo','Promovido'))
 ORDER BY t.operational_day DESC,t.updated_at DESC LIMIT 200
$$;
CREATE OR REPLACE FUNCTION public.sri_p03_my_unresolved()
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT * FROM private.sri_p03_my_unresolved()
$$;
REVOKE ALL ON FUNCTION private.sri_p03_my_unresolved(),public.sri_p03_my_unresolved() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sri_p03_my_unresolved(),private.sri_p03_my_unresolved() TO authenticated;

-- SOURCE sql/2026-11-24_sri_p03_historico_datas.sql
-- Pacote 03 — API histórica com filtros por data, leitura sem alterar estado.

CREATE OR REPLACE FUNCTION private.sri_p03_my_treatments_page(
 p_from date DEFAULT NULL,p_to date DEFAULT NULL,p_before bigint DEFAULT NULL,p_limit integer DEFAULT 200
) RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles p
    WHERE p.id=auth.uid() AND p.role='operator' AND p.operational_status IN ('Ativo','Promovido'))
 THEN RAISE EXCEPTION 'Acesso restrito ao operador autenticado'; END IF;
 IF p_from IS NOT NULL AND p_to IS NOT NULL AND p_from>p_to
 THEN RAISE EXCEPTION 'Período de consulta inválido'; END IF;
 IF p_from IS NOT NULL AND p_to IS NOT NULL AND p_to-p_from>366
 THEN RAISE EXCEPTION 'Intervalo máximo de 367 dias'; END IF;
 RETURN QUERY
 SELECT jsonb_build_object('id',h.id,'action',h.action,'notes',h.notes,
   'created_at',h.created_at,'task_id',h.task_id,'protocol_number',t.protocol_number,
   'base_name',t.base_name,'area_name',t.area_name)
 FROM public.daily_operator_treatments h
 JOIN public.daily_operator_tasks t ON t.id=h.task_id
 WHERE h.actor_id=auth.uid()
 AND (p_from IS NULL OR h.created_at >= (p_from::timestamp AT TIME ZONE 'America/Sao_Paulo'))
 AND (p_to IS NULL OR h.created_at < ((p_to+1)::timestamp AT TIME ZONE 'America/Sao_Paulo'))
 AND (p_before IS NULL OR h.id<p_before)
 ORDER BY h.id DESC
 LIMIT greatest(1,least(coalesce(p_limit,200),200));
END $$;

CREATE OR REPLACE FUNCTION public.sri_p03_my_treatments_page(
 p_from date DEFAULT NULL,p_to date DEFAULT NULL,p_before bigint DEFAULT NULL,p_limit integer DEFAULT 200
) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT * FROM private.sri_p03_my_treatments_page(p_from,p_to,p_before,p_limit);
$$;
REVOKE ALL ON FUNCTION private.sri_p03_my_treatments_page(date,date,bigint,integer),
 public.sri_p03_my_treatments_page(date,date,bigint,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.sri_p03_my_treatments_page(date,date,bigint,integer),
 public.sri_p03_my_treatments_page(date,date,bigint,integer) TO authenticated;

-- Lista de snapshots reais por data operacional. Os indicadores globais são exibidos
-- somente a administrador/gestor; supervisores recebem apenas a referência de data/turno.
CREATE OR REPLACE FUNCTION private.sri_p03_history_snapshots(p_day date)
RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE v_role text;
BEGIN
 SELECT p.role INTO v_role FROM public.profiles p WHERE p.id=auth.uid();
 IF v_role IS NULL OR v_role NOT IN ('admin','manager','supervisor','assistant') OR p_day IS NULL
 THEN RAISE EXCEPTION 'Consulta histórica indisponível'; END IF;
 RETURN QUERY
 SELECT jsonb_build_object(
   'id',s.id,'operational_day',s.operational_day,'shift_label',s.shift_label,
   'created_at',s.created_at,'protocol_count',
     CASE WHEN v_role IN ('admin','manager') THEN s.protocol_count ELSE NULL END,
   'indicators',CASE WHEN v_role IN ('admin','manager') THEN s.indicators ELSE NULL END)
 FROM public.daily_result_snapshots s
 WHERE s.operational_day=p_day
   AND (v_role IN ('admin','manager') OR
     (s.team_id IS NULL OR private.is_supervisor_of(s.team_id)))
 ORDER BY s.created_at DESC,s.id DESC LIMIT 100;
END $$;
CREATE OR REPLACE FUNCTION public.sri_p03_history_snapshots(p_day date)
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT * FROM private.sri_p03_history_snapshots(p_day);
$$;

-- Detalhe dos protocolos distribuídos para o snapshot escolhido.
-- Proteção por equipe/vínculo: não expõe carteiras de outros supervisores.
CREATE OR REPLACE FUNCTION private.sri_p03_history_tasks(
 p_snapshot uuid,p_after text DEFAULT NULL,p_limit integer DEFAULT 200
) RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE v_role text;
BEGIN
 SELECT p.role INTO v_role FROM public.profiles p WHERE p.id=auth.uid();
 IF v_role IS NULL OR v_role NOT IN ('admin','manager','supervisor','assistant') OR p_snapshot IS NULL
 THEN RAISE EXCEPTION 'Consulta histórica indisponível'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.daily_result_snapshots s WHERE s.id=p_snapshot
   AND (v_role IN ('admin','manager') OR
        s.team_id IS NULL OR private.is_supervisor_of(s.team_id)))
 THEN RAISE EXCEPTION 'Apuração não autorizada'; END IF;
 RETURN QUERY
 SELECT jsonb_build_object('protocol_number',t.protocol_number,'operator_name',op.full_name,
   'criticality',t.criticality,'source_status',t.source_status,
   'work_status',t.work_status,'treatment_status',t.treatment_status,
   'due_date',t.due_date,'base_name',t.base_name,'area_name',t.area_name,
   'snapshot_id',t.snapshot_id)
 FROM public.daily_operator_tasks t
 JOIN public.profiles op ON op.id=t.operator_user_id
 WHERE t.snapshot_id=p_snapshot
 AND (p_after IS NULL OR t.protocol_number>p_after)
 AND (v_role IN ('admin','manager') OR
   EXISTS(SELECT 1 FROM public.profiles me
    WHERE me.id=auth.uid() AND me.role IN ('supervisor','assistant')
     AND (op.supervisor_id=auth.uid()
        OR EXISTS(SELECT 1 FROM public.team_memberships member
                  JOIN public.team_memberships owner ON owner.team_id=member.team_id
                  WHERE member.user_id=op.id AND owner.user_id=auth.uid()))))
 ORDER BY t.protocol_number,t.id
 LIMIT greatest(1,least(coalesce(p_limit,200),200));
END $$;
CREATE OR REPLACE FUNCTION public.sri_p03_history_tasks(
 p_snapshot uuid,p_after text DEFAULT NULL,p_limit integer DEFAULT 200
) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT * FROM private.sri_p03_history_tasks(p_snapshot,p_after,p_limit);
$$;
REVOKE ALL ON FUNCTION private.sri_p03_history_snapshots(date),
 public.sri_p03_history_snapshots(date),private.sri_p03_history_tasks(uuid,text,integer),
 public.sri_p03_history_tasks(uuid,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.sri_p03_history_snapshots(date),
 public.sri_p03_history_snapshots(date),private.sri_p03_history_tasks(uuid,text,integer),
 public.sri_p03_history_tasks(uuid,text,integer) TO authenticated;

-- SOURCE sql/2026-11-24_sri_p03_perfil_assistente.sql
-- MEL-EXTRA-003: Assistant profile; same operational team scope as Supervisor.
-- Apply after the other Package 03 migrations, in one transaction.

ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_role_check;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_role_check
 CHECK (role IN ('operator','viewer','supervisor','assistant','manager','admin'));

-- Explicit whitelist of privileged functions. Only role authorization comparisons are amended,
-- never change manager/admin-only permissions into supervisor permissions.
DO $assistant_funcs$
DECLARE r record; src text; upd text;
BEGIN
 FOR r IN SELECT n.nspname,p.proname,p.oid
   FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE p.prokind='f' AND (
      (n.nspname='private' AND p.proname IN (
        'is_supervisor_of','sri_supervisor_can_view_user','sri_reconcile_presence',
        'sri_reconciliation_counts','sri_list_reconciliation','sri_decide_reconciliation',
        'sri_rename_user_impl','sri_movement_read'))
      OR (n.nspname='public' AND p.proname IN (
        'admin_change_user_role','sri_set_user_team','management_summary',
        'publish_general_operator_tasks','sri_general_distribution_candidates',
        'sri_result_closure_overview','sri_p03_productivity'))
     )
 LOOP
  src:=pg_get_functiondef(r.oid);
  upd:=src;
  upd:=replace(upd, 'role=''supervisor''','role IN (''supervisor'',''assistant'')');
  upd:=replace(upd, 'role = ''supervisor''','role IN (''supervisor'',''assistant'')');
  upd:=replace(upd, 'role_name NOT IN (''admin'',''manager'',''supervisor'')',
                        'role_name NOT IN (''admin'',''manager'',''supervisor'',''assistant'')');
  upd:=replace(upd, 'role IN (''admin'',''manager'',''supervisor'')',
                        'role IN (''admin'',''manager'',''supervisor'',''assistant'')');
  upd:=replace(upd, 'v_role NOT IN (''operator'',''supervisor'')',
                        'v_role NOT IN (''operator'',''supervisor'',''assistant'')');
  upd:=replace(upd, 'v_role NOT IN (''operator'',''supervisor'')',
                        'v_role NOT IN (''operator'',''supervisor'',''assistant'')');
  upd:=replace(upd, 'v_sup_role NOT IN (''supervisor'',''manager'',''admin'')',
                        'v_sup_role NOT IN (''supervisor'',''assistant'',''manager'',''admin'')');
  upd:=replace(upd, 'v_sup_role=''supervisor''',
                        'v_sup_role IN (''supervisor'',''assistant'')');
  upd:=replace(upd, 'v_actor=''manager'' AND v_role NOT IN (''operator'',''supervisor'')',
                        'v_actor=''manager'' AND v_role NOT IN (''operator'',''supervisor'',''assistant'')');
  upd:=replace(upd, 'p_new_role NOT IN (''operator'',''viewer'',''supervisor'',''manager'',''admin'')',
                        'p_new_role NOT IN (''operator'',''viewer'',''supervisor'',''assistant'',''manager'',''admin'')');
  IF src IS DISTINCT FROM upd THEN EXECUTE upd; END IF;
 END LOOP;
END $assistant_funcs$;

-- All existing RLS scopes remain identical; only supervisor role predicate
-- is extended to assistant role, without manager/admin privilege broadening.
DO $assistant_policies$
DECLARE r record; oldq text; newq text; oldw text; neww text; statement text;
BEGIN
 FOR r IN SELECT * FROM pg_policies WHERE schemaname='public'
   AND (coalesce(qual,'') LIKE '%role = ''supervisor''::text%'
     OR coalesce(with_check,'') LIKE '%role = ''supervisor''::text%')
 LOOP
  oldq:=r.qual;oldw:=r.with_check;
  newq:=replace(oldq, 'role = ''supervisor''::text',
         'role = ANY (ARRAY[''supervisor''::text,''assistant''::text])');
  neww:=replace(oldw, 'role = ''supervisor''::text',
         'role = ANY (ARRAY[''supervisor''::text,''assistant''::text])');
  statement:=format('ALTER POLICY %I ON public.%I',r.policyname,r.tablename);
  IF newq IS DISTINCT FROM oldq THEN statement:=statement||' USING ('||newq||')'; END IF;
  IF neww IS DISTINCT FROM oldw THEN statement:=statement||' WITH CHECK ('||neww||')'; END IF;
  IF statement<>format('ALTER POLICY %I ON public.%I',r.policyname,r.tablename)
  THEN EXECUTE statement; END IF;
 END LOOP;
END $assistant_policies$;

-- SOURCE sql/2026-11-25_sri_p03_historico_imutavel.sql
-- Apply after the six Package 03 release migrations. Append-only capture starts
-- at installation. Earlier states cannot be inferred from mutable tasks.

CREATE TABLE IF NOT EXISTS private.sri_p03_task_versions (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 task_id uuid NOT NULL,
 snapshot_id uuid NOT NULL,
 operational_day date NOT NULL,
 protocol_number text NOT NULL,
 team_id uuid,
 captured_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 payload jsonb NOT NULL
);
ALTER TABLE private.sri_p03_task_versions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.sri_p03_task_versions FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS sri_p03_version_snapshot_protocol
 ON private.sri_p03_task_versions(snapshot_id,protocol_number,captured_at DESC,id DESC);

CREATE OR REPLACE FUNCTION private.sri_p03_capture_task()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE operator_name text; team_name text;
BEGIN
 SELECT p.full_name INTO operator_name FROM public.profiles p WHERE p.id=NEW.operator_user_id;
 SELECT t.name INTO team_name FROM public.teams t WHERE t.id=NEW.team_id;
 INSERT INTO private.sri_p03_task_versions(task_id,snapshot_id,operational_day,protocol_number,team_id,payload)
 VALUES(NEW.id,NEW.snapshot_id,NEW.operational_day,NEW.protocol_number,NEW.team_id,
   to_jsonb(NEW)||jsonb_build_object('operator_name',operator_name,'team_name',team_name));
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION private.sri_p03_capture_task() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS sri_p03_capture_task ON public.daily_operator_tasks;
CREATE TRIGGER sri_p03_capture_task AFTER INSERT OR UPDATE ON public.daily_operator_tasks
 FOR EACH ROW EXECUTE FUNCTION private.sri_p03_capture_task();

ALTER TABLE public.daily_operator_treatments ADD COLUMN IF NOT EXISTS event_context jsonb;
CREATE OR REPLACE FUNCTION private.sri_p03_capture_treatment_context()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 -- Always derive the context on the server, even if a caller supplies a value.
 SELECT jsonb_build_object('protocol_number',t.protocol_number,
  'base_name',t.base_name,'area_name',t.area_name,'source_status',t.source_status,
  'work_status',private.sri_p03_status_work(NEW.action),'version','20261125')
 INTO NEW.event_context FROM public.daily_operator_tasks t WHERE t.id=NEW.task_id;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION private.sri_p03_capture_treatment_context() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS sri_p03_capture_treatment_context ON public.daily_operator_treatments;
CREATE TRIGGER sri_p03_capture_treatment_context BEFORE INSERT ON public.daily_operator_treatments
 FOR EACH ROW EXECUTE FUNCTION private.sri_p03_capture_treatment_context();

CREATE OR REPLACE FUNCTION private.sri_p03_my_treatments_page(
 p_from date DEFAULT NULL,p_to date DEFAULT NULL,p_before bigint DEFAULT NULL,p_limit integer DEFAULT 200
) RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid()
  AND p.role='operator' AND p.operational_status IN ('Ativo','Promovido'))
 THEN RAISE EXCEPTION 'Acesso restrito ao operador autenticado'; END IF;
 IF p_from>p_to OR p_to-p_from>366 THEN RAISE EXCEPTION 'Período de consulta inválido'; END IF;
 RETURN QUERY SELECT jsonb_build_object('id',h.id::text,'action',h.action,'notes',h.notes,
  'created_at',h.created_at,'task_id',h.task_id,
  'protocol_number',coalesce(h.event_context->>'protocol_number',t.protocol_number),
  'base_name',h.event_context->>'base_name','area_name',h.event_context->>'area_name',
  'context_available',h.event_context IS NOT NULL)
 FROM public.daily_operator_treatments h LEFT JOIN public.daily_operator_tasks t ON t.id=h.task_id
 WHERE h.actor_id=auth.uid()
 AND (p_from IS NULL OR h.created_at >= (p_from::timestamp AT TIME ZONE 'America/Sao_Paulo'))
 AND (p_to IS NULL OR h.created_at < ((p_to+1)::timestamp AT TIME ZONE 'America/Sao_Paulo'))
 AND (p_before IS NULL OR h.id<p_before)
 ORDER BY h.id DESC LIMIT greatest(1,least(coalesce(p_limit,200),200));
END $$;

CREATE OR REPLACE FUNCTION private.sri_p03_history_tasks(
 p_snapshot uuid,p_after text DEFAULT NULL,p_limit integer DEFAULT 200
) RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE viewer_role text; snapshot_day date;
BEGIN
 SELECT p.role INTO viewer_role FROM public.profiles p WHERE p.id=auth.uid();
 IF viewer_role IS NULL OR viewer_role NOT IN ('admin','manager','supervisor','assistant')
 THEN RAISE EXCEPTION 'Consulta histórica indisponível'; END IF;
 SELECT s.operational_day INTO snapshot_day FROM public.daily_result_snapshots s WHERE s.id=p_snapshot
 AND (viewer_role IN ('admin','manager') OR s.team_id IS NULL OR private.is_supervisor_of(s.team_id));
 IF NOT FOUND THEN RAISE EXCEPTION 'Apuração não autorizada'; END IF;
 RETURN QUERY
 SELECT v.payload||jsonb_build_object('captured_at',v.captured_at)
 FROM (
  SELECT DISTINCT ON(h.protocol_number) h.*
  FROM private.sri_p03_task_versions h WHERE h.snapshot_id=p_snapshot
  AND h.captured_at<((snapshot_day+1)::timestamp AT TIME ZONE 'America/Sao_Paulo')
  AND (p_after IS NULL OR h.protocol_number>p_after)
  ORDER BY h.protocol_number,h.captured_at DESC,h.id DESC
 ) v
 WHERE viewer_role IN ('admin','manager')
 OR (v.team_id IS NOT NULL AND private.is_supervisor_of(v.team_id))
 ORDER BY v.protocol_number LIMIT greatest(1,least(coalesce(p_limit,200),200));
END $$;
REVOKE ALL ON FUNCTION private.sri_p03_my_treatments_page(date,date,bigint,integer),
 private.sri_p03_history_tasks(uuid,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.sri_p03_my_treatments_page(date,date,bigint,integer),
 private.sri_p03_history_tasks(uuid,text,integer) TO authenticated;

-- SOURCE sql/2026-11-25_sri_p03_escopo_publicacao.sql
-- Scope every write performed by a general publication, including carried
-- assignments and deactivation of older rounds.

CREATE OR REPLACE FUNCTION private.sri_p03_can_manage_task(p_operator uuid,p_team uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT private.is_manager() OR EXISTS(
  SELECT 1 FROM public.profiles me JOIN public.profiles operator ON operator.id=p_operator
  WHERE me.id=auth.uid() AND me.role IN ('supervisor','assistant')
  AND (operator.supervisor_id=me.id OR (p_team IS NOT NULL AND private.is_supervisor_of(p_team)))
 );
$$;
REVOKE ALL ON FUNCTION private.sri_p03_can_manage_task(uuid,uuid) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION private.sri_p03_preserve_open_tasks(
 p_snapshot uuid,p_day date,p_shift text,p_scope_team uuid,p_revision bigint)
RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE v_count integer:=0;
BEGIN
 IF EXISTS(
  SELECT 1 FROM public.daily_operator_tasks old
  JOIN public.daily_result_snapshots os ON os.id=old.snapshot_id
  JOIN public.daily_operator_tasks fresh ON fresh.snapshot_id=p_snapshot
       AND fresh.protocol_number=old.protocol_number
  WHERE old.snapshot_id<>p_snapshot AND old.active
   AND old.operational_day=p_day AND old.shift_label=p_shift
   AND os.team_id IS NOT DISTINCT FROM p_scope_team
   AND private.sri_p03_can_manage_task(old.operator_user_id,old.team_id)
   AND old.operator_user_id IS DISTINCT FROM fresh.operator_user_id
   AND (old.work_status<>'pending' OR EXISTS(
    SELECT 1 FROM public.daily_operator_treatments h WHERE h.task_id=old.id))
 ) THEN
  RAISE EXCEPTION 'Distribuição conflita com tratativa prévia: revisão manual obrigatória';
 END IF;
 WITH prior AS (
  SELECT DISTINCT ON(old.protocol_number) old.*
  FROM public.daily_operator_tasks old
  JOIN public.daily_result_snapshots os ON os.id=old.snapshot_id
  WHERE old.snapshot_id<>p_snapshot AND old.active
   AND old.operational_day=p_day AND old.shift_label=p_shift
   AND os.team_id IS NOT DISTINCT FROM p_scope_team
   AND private.sri_p03_can_manage_task(old.operator_user_id,old.team_id)
   AND old.work_status<>'completed_in_tool'
   AND private.sri_p03_status_sigo(old.treatment_status) IS DISTINCT FROM 3
   AND NOT EXISTS (SELECT 1 FROM public.daily_operator_tasks fresh
     WHERE fresh.snapshot_id=p_snapshot AND fresh.protocol_number=old.protocol_number)
  ORDER BY old.protocol_number,old.updated_at DESC,old.id DESC
 )
 INSERT INTO public.daily_operator_tasks
  (snapshot_id,team_id,operational_day,shift_label,protocol_number,operator_user_id,
   criticality,due_situation,sla_band,channel,source_status,work_status,
   treatment_status,active,distribution_revision,priority_reason,due_date,base_name,area_name)
 SELECT p_snapshot,old.team_id,p_day,p_shift,old.protocol_number,old.operator_user_id,
  old.criticality,old.due_situation,old.sla_band,old.channel,old.source_status,
  old.work_status,old.treatment_status,true,p_revision,old.priority_reason,old.due_date,
  old.base_name,old.area_name
 FROM prior old JOIN public.profiles op ON op.id=old.operator_user_id
  AND op.role='operator' AND op.operational_status IN ('Ativo','Promovido')
 ON CONFLICT(snapshot_id,protocol_number) DO NOTHING;
 GET DIAGNOSTICS v_count=ROW_COUNT;
 UPDATE public.daily_operator_tasks t SET distribution_revision=p_revision,updated_at=now()
 WHERE t.snapshot_id=p_snapshot AND t.active AND t.distribution_revision<>p_revision
   AND private.sri_p03_can_manage_task(t.operator_user_id,t.team_id)
   AND t.work_status<>'completed_in_tool'
   AND private.sri_p03_status_sigo(t.treatment_status) IS DISTINCT FROM 3;
 IF v_count>0 THEN
  INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
  VALUES(auth.uid(),'P03_UNFINISHED_CARRIED','daily_result',p_snapshot::text,
    jsonb_build_object('day',p_day,'shift',p_shift,'carried',v_count,'revision',p_revision));
 END IF;
 RETURN v_count;
END $$;
REVOKE ALL ON FUNCTION private.sri_p03_preserve_open_tasks(uuid,date,text,uuid,bigint) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.publish_general_operator_tasks(p_snapshot uuid, p_revision bigint, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_day date;v_shift text;v_state jsonb;v_revision bigint;v_latest uuid;
 v_assignment record;v_protocol text;v_opid text;v_user uuid;v_team uuid;
 v_role text;v_status text;v_supervisor uuid;v_num_teams integer;
 v_criticality text;v_detail jsonb;v_published integer:=0;v_changed integer:=0;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão obrigatória'; END IF;
 IF NOT (private.is_manager() OR EXISTS(SELECT 1 FROM public.profiles p
  WHERE p.id=auth.uid() AND p.role IN ('supervisor','assistant'))) THEN
  RAISE EXCEPTION 'Publicação restrita à gestão e supervisão'; END IF;
 IF p_details IS NULL OR jsonb_typeof(p_details)<>'object' THEN
  RAISE EXCEPTION 'Detalhes inválidos';END IF;
 SELECT s.operational_day,s.shift_label,d.state,d.revision
 INTO v_day,v_shift,v_state,v_revision
 FROM public.daily_result_snapshots s JOIN public.daily_result_distributions d ON d.snapshot_id=s.id
 WHERE s.id=p_snapshot AND s.team_id IS NULL FOR SHARE OF d;
 IF NOT FOUND THEN RAISE EXCEPTION 'Resultado geral não publicado';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||v_day::text,0));
 IF v_revision IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'A distribuição mudou: recarregue o resultado';END IF;
 IF EXISTS(SELECT 1 FROM public.sri_general_day_closures c WHERE c.operational_day=v_day)
  OR EXISTS(SELECT 1 FROM public.sri_result_day_closures c WHERE c.operational_day=v_day
   AND c.status IN('closed','closed_with_pending')) THEN
  RAISE EXCEPTION 'Dia operacional encerrado: distribuição bloqueada';END IF;
 SELECT s.id INTO v_latest FROM public.daily_result_snapshots s
 WHERE s.team_id IS NULL AND s.operational_day=v_day AND s.shift_label=v_shift
 ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
 IF v_latest IS DISTINCT FROM p_snapshot THEN
  RAISE EXCEPTION 'Apuração geral anterior: recupere a importação mais recente';END IF;
 IF jsonb_typeof(v_state->'assignments') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'Estrutura da distribuição inválida';END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(v_state->'assignments'))>15000 THEN
  RAISE EXCEPTION 'Limite de 15 mil atribuições por rodada excedido';END IF;
 -- Todos os vínculos são validados ANTES de efetuar qualquer INSERT.
 FOR v_assignment IN SELECT key,value FROM jsonb_each(v_state->'assignments') LOOP
  v_protocol:=btrim(v_assignment.key);v_opid:=v_assignment.value->>'opId';
  IF length(v_protocol) NOT BETWEEN 1 AND 100 OR v_opid IS NULL
    OR v_opid !~ '^acct:[0-9a-fA-F-]{36}$' THEN
    RAISE EXCEPTION 'Operador não cadastrado em protocolo: %',left(v_protocol,100);
  END IF;
  v_user:=substring(v_opid FROM 6)::uuid;
  SELECT p.role,p.operational_status,p.supervisor_id INTO v_role,v_status,v_supervisor
  FROM public.profiles p WHERE p.id=v_user;
  IF NOT FOUND OR v_role<>'operator' OR v_status NOT IN('Ativo','Promovido') THEN
    RAISE EXCEPTION 'Operador inativo ou inválido para o protocolo %',v_protocol; END IF;
  SELECT count(*),(array_agg(tm.team_id ORDER BY tm.team_id))[1] INTO v_num_teams,v_team
  FROM public.team_memberships tm JOIN public.teams t ON t.id=tm.team_id AND t.active
  WHERE tm.user_id=v_user;
  IF v_num_teams>1 THEN
    RAISE EXCEPTION 'Operador possui mais de uma equipe ativa; revise vínculo antes de distribuir'; END IF;
  IF EXISTS(SELECT 1 FROM public.daily_operator_tasks t WHERE t.operator_user_id=v_user AND t.active
    AND t.team_id IS DISTINCT FROM v_team AND private.sri_task_blocks_transfer(t.operational_day,t.team_id,t.shift_label)) THEN
    RAISE EXCEPTION 'Operador possui vínculo conflitante; a gestão deve revisar antes de distribuir'; END IF;
  IF NOT (private.is_manager() OR v_supervisor=(SELECT auth.uid())
   OR (v_team IS NOT NULL AND private.is_supervisor_of(v_team))) THEN
    RAISE EXCEPTION 'Operador fora da equipe sob responsabilidade da supervisão';END IF;
 END LOOP;
 FOR v_assignment IN SELECT key,value FROM jsonb_each(v_state->'assignments') LOOP
  v_protocol:=btrim(v_assignment.key);
  v_user:=substring(v_assignment.value->>'opId' FROM 6)::uuid;
  SELECT (array_agg(tm.team_id ORDER BY tm.team_id))[1] INTO v_team
  FROM public.team_memberships tm JOIN public.teams t ON t.id=tm.team_id AND t.active
  WHERE tm.user_id=v_user;
  IF v_team IS NOT NULL THEN
   -- Compatibilidade com FK de vínculo existente; só em equipe explicitamente cadastrada.
   INSERT INTO public.operator_links(team_id,user_id,operator_name,linked_by)
   VALUES(v_team,v_user,'USER:'||v_user::text,(SELECT auth.uid()))
   ON CONFLICT (team_id,user_id) DO NOTHING;
  END IF;
  v_detail:=COALESCE(p_details->v_protocol,'{}'::jsonb);
  IF jsonb_typeof(v_detail)<>'object' THEN v_detail:='{}'::jsonb;END IF;
  v_criticality:=COALESCE(NULLIF(v_state->'criticities'->v_protocol->>'value',''),
     NULLIF(v_detail->>'criticality',''));
  INSERT INTO public.daily_operator_tasks
  (snapshot_id,team_id,operational_day,shift_label,protocol_number,operator_user_id,
   criticality,due_situation,sla_band,channel,source_status,distribution_revision,active,priority_reason,due_date,base_name,area_name)
  VALUES(p_snapshot,v_team,v_day,v_shift,v_protocol,v_user,
   left(v_criticality,80),left(v_detail->>'situation',80),left(v_detail->>'sla',50),
   left(v_detail->>'channel',80),
   left(v_detail->>'status',80),v_revision,true,private.sri_priority_reason(v_detail->>'priority_reason'),private.sri_priority_date(v_detail->>'due_date'),left(v_detail->>'base',120),left(v_detail->>'area',120))
  ON CONFLICT(snapshot_id,protocol_number) DO UPDATE SET
   operator_user_id=EXCLUDED.operator_user_id,team_id=EXCLUDED.team_id,
   criticality=EXCLUDED.criticality,priority_reason=EXCLUDED.priority_reason,due_date=EXCLUDED.due_date,due_situation=EXCLUDED.due_situation,
   sla_band=EXCLUDED.sla_band,channel=EXCLUDED.channel,
   source_status=COALESCE(EXCLUDED.source_status,daily_operator_tasks.source_status),base_name=COALESCE(EXCLUDED.base_name,daily_operator_tasks.base_name),area_name=COALESCE(EXCLUDED.area_name,daily_operator_tasks.area_name),
   active=true,distribution_revision=EXCLUDED.distribution_revision,updated_at=now(),
   work_status=public.daily_operator_tasks.work_status;
  v_published:=v_published+1;
 END LOOP;
 PERFORM private.sri_p03_preserve_open_tasks(p_snapshot,v_day,v_shift,NULL::uuid,v_revision);
 UPDATE public.daily_operator_tasks t SET active=false,updated_at=now()
 WHERE t.snapshot_id=p_snapshot AND t.active AND t.distribution_revision<>v_revision
 AND private.sri_p03_can_manage_task(t.operator_user_id,t.team_id);
 GET DIAGNOSTICS v_changed=ROW_COUNT;
 -- Versionamento: a nova rodada desativa a anterior SOMENTE deste turno/apuração geral.
 UPDATE public.daily_operator_tasks t SET active=false,updated_at=now()
 WHERE t.snapshot_id<>p_snapshot AND t.operational_day=v_day AND t.shift_label=v_shift
  AND t.active AND private.sri_p03_can_manage_task(t.operator_user_id,t.team_id)
  AND EXISTS(SELECT 1 FROM public.daily_result_snapshots s
    WHERE s.id=t.snapshot_id AND s.team_id IS NULL);
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES((SELECT auth.uid()),'GENERAL_OPERATOR_TASKS_PUBLISHED','daily_result',p_snapshot::text,
  jsonb_build_object('revision',v_revision,'published',v_published,'prior_revision_removed',v_changed));
 RETURN jsonb_build_object('published',v_published,'unlinked',0,'revision',v_revision);
END;
$function$
;



