CREATE INDEX IF NOT EXISTS sri_p03_monitor_level_date ON private.sri_monitor_events(severity,occurred_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS sri_p03_monitor_date ON private.sri_monitor_events(occurred_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS private.sri_p03_monitor_occurrences(
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 event_id bigint NOT NULL REFERENCES private.sri_monitor_events(id) ON DELETE RESTRICT,
 actor_id uuid NOT NULL,
 occurred_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE private.sri_p03_monitor_occurrences ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.sri_p03_monitor_occurrences FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS sri_p03_occurrence_actor_time ON private.sri_p03_monitor_occurrences(actor_id,occurred_at);
CREATE INDEX IF NOT EXISTS sri_p03_occurrence_event_page ON private.sri_p03_monitor_occurrences(event_id,id DESC);

CREATE OR REPLACE FUNCTION private.sri_monitor_write(p_severity text,p_code text,p_module text,p_version text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); event_key bigint;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=actor) THEN RAISE EXCEPTION 'Sessão obrigatória'; END IF;
 IF p_severity IS NULL OR p_severity NOT IN ('INFO','SUCCESS','WARN','ERROR','FATAL')
 OR p_code IS NULL OR p_code NOT IN ('JS_ERROR','PROMISE_ERROR','PUBLISH_ERROR','PUBLISH_OK','MISSING_METADATA','RPC_ERROR','REST_ERROR','OPERATION_AUDIT','SLOW_RPC','AUTH_OK','AUTH_ERROR')
 OR p_module IS NULL OR p_module NOT IN ('Interface','Distribuição','Carteira','Supabase','Autenticação')
 OR p_version IS DISTINCT FROM 'pacote03-20261124' THEN RAISE EXCEPTION 'Evento inválido'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-monitor:'||actor::text,0));
 IF (SELECT count(*) FROM private.sri_p03_monitor_occurrences WHERE actor_id=actor AND occurred_at>now()-interval '1 minute')>=200 THEN RETURN; END IF;
 SELECT id INTO event_key FROM private.sri_monitor_events WHERE actor_id=actor AND code=p_code
 AND module=p_module AND severity=p_severity AND version=p_version AND occurred_at>now()-interval '5 minutes'
 ORDER BY id DESC LIMIT 1;
 IF event_key IS NULL THEN
  IF (SELECT count(*) FROM private.sri_monitor_events WHERE actor_id=actor AND occurred_at>now()-interval '1 minute')>=20 THEN RETURN; END IF;
  INSERT INTO private.sri_monitor_events(actor_id,severity,code,module,version)
  VALUES(actor,p_severity,p_code,p_module,p_version) RETURNING id INTO event_key;
 ELSE
  UPDATE private.sri_monitor_events SET occurrences=occurrences+1,last_at=clock_timestamp() WHERE id=event_key;
 END IF;
 INSERT INTO private.sri_p03_monitor_occurrences(event_id,actor_id) VALUES(event_key,actor);
END $$;

CREATE OR REPLACE FUNCTION private.sri_monitor_read(p_from timestamptz,p_to timestamptz,p_level text,p_before bigint DEFAULT NULL)
RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role='admin') THEN RAISE EXCEPTION 'Acesso exclusivo ao administrador'; END IF;
 IF p_from IS NULL OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>interval '367 days' THEN RAISE EXCEPTION 'Período inválido'; END IF;
 RETURN QUERY SELECT jsonb_build_object('id',e.id::text,'occurred_at',e.occurred_at,'last_at',e.last_at,
 'severity',e.severity,'code',e.code,'module',e.module,'version',e.version,'occurrences',e.occurrences,'responsavel',p.full_name)
 FROM private.sri_monitor_events e LEFT JOIN public.profiles p ON p.id=e.actor_id
 WHERE e.occurred_at>=p_from AND e.occurred_at<p_to AND (p_level IS NULL OR e.severity=p_level)
 AND (p_before IS NULL OR e.id<p_before) ORDER BY e.id DESC LIMIT 200;
END $$;

CREATE OR REPLACE FUNCTION private.sri_p03_monitor_occurrences(p_event bigint,p_before bigint DEFAULT NULL)
RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role='admin') THEN RAISE EXCEPTION 'Acesso exclusivo ao administrador'; END IF;
 RETURN QUERY SELECT jsonb_build_object('id',o.id::text,'event_id',o.event_id::text,'occurred_at',o.occurred_at)
 FROM private.sri_p03_monitor_occurrences o WHERE o.event_id=p_event AND (p_before IS NULL OR o.id<p_before)
 ORDER BY o.id DESC LIMIT 200;
END $$;
CREATE OR REPLACE FUNCTION public.sri_p03_monitor_occurrences(p_event bigint,p_before bigint DEFAULT NULL)
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT * FROM private.sri_p03_monitor_occurrences(p_event,p_before);
$$;
REVOKE ALL ON FUNCTION private.sri_monitor_write(text,text,text,text),
 private.sri_monitor_read(timestamptz,timestamptz,text,bigint),
 private.sri_p03_monitor_occurrences(bigint,bigint),public.sri_p03_monitor_occurrences(bigint,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.sri_monitor_write(text,text,text,text),
 private.sri_monitor_read(timestamptz,timestamptz,text,bigint),
 private.sri_p03_monitor_occurrences(bigint,bigint),public.sri_p03_monitor_occurrences(bigint,bigint) TO authenticated;

-- SOURCE sql/2026-11-25_sri_p03_continuidade_carteira.sql
ALTER TABLE public.daily_operator_tasks ADD COLUMN IF NOT EXISTS carried_from_task_id uuid
 REFERENCES public.daily_operator_tasks(id) ON DELETE RESTRICT;
ALTER TABLE public.daily_operator_tasks ADD COLUMN IF NOT EXISTS completed_operational_day date;
CREATE OR REPLACE FUNCTION private.sri_carry_task_status()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE prior public.daily_operator_tasks%rowtype; completed boolean;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(
  'sri-protocol-scope:'||(SELECT coalesce(s.team_id::text,'general') FROM public.daily_result_snapshots s WHERE s.id=NEW.snapshot_id)||':'||NEW.protocol_number,0));
 IF EXISTS(
  SELECT 1 FROM public.daily_operator_tasks newer
  JOIN public.daily_result_snapshots newer_snapshot ON newer_snapshot.id=newer.snapshot_id
  JOIN public.daily_result_snapshots target_snapshot ON target_snapshot.id=NEW.snapshot_id
  WHERE newer.protocol_number=NEW.protocol_number AND newer.operational_day>NEW.operational_day
  AND newer_snapshot.team_id IS NOT DISTINCT FROM target_snapshot.team_id
 ) THEN RAISE EXCEPTION 'Existe carteira de data posterior para este protocolo. Atualize a apuração antes de publicar'; END IF;
 SELECT task.* INTO prior FROM public.daily_operator_tasks task
 JOIN public.daily_result_snapshots old_snapshot ON old_snapshot.id=task.snapshot_id
 JOIN public.daily_result_snapshots new_snapshot ON new_snapshot.id=NEW.snapshot_id
 WHERE task.protocol_number=NEW.protocol_number AND task.snapshot_id<>NEW.snapshot_id
 AND task.operational_day<=NEW.operational_day
 AND old_snapshot.team_id IS NOT DISTINCT FROM new_snapshot.team_id
 AND (task.active OR task.work_status='completed_in_tool' OR private.sri_p03_status_sigo(task.treatment_status)=3)
 ORDER BY task.operational_day DESC,task.updated_at DESC,task.id DESC LIMIT 1;
 IF NOT FOUND THEN RETURN NEW; END IF;
 completed:=prior.work_status='completed_in_tool' OR coalesce(private.sri_p03_status_sigo(prior.treatment_status)=3,false);
 IF prior.operator_user_id IS DISTINCT FROM NEW.operator_user_id
 AND (prior.work_status<>'pending' OR completed OR EXISTS(
  SELECT 1 FROM public.daily_operator_treatments h WHERE h.task_id=prior.id)) THEN
  RAISE EXCEPTION 'Protocolo com tratativa anterior: concilie o responsável antes de redistribuir';
 END IF;
 IF prior.operator_user_id=NEW.operator_user_id THEN
  NEW.carried_from_task_id:=prior.id;
  NEW.treatment_status:=prior.treatment_status;
  NEW.work_status:=CASE WHEN completed THEN 'completed_in_tool' ELSE prior.work_status END;
  NEW.completed_operational_day:=CASE WHEN completed THEN coalesce(prior.completed_operational_day,prior.operational_day) END;
  IF completed AND NEW.completed_operational_day<NEW.operational_day THEN NEW.active:=false; END IF;
  NEW.base_name:=coalesce(nullif(btrim(NEW.base_name),''),prior.base_name);
  NEW.area_name:=coalesce(nullif(btrim(NEW.area_name),''),prior.area_name);
 END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION private.sri_p03_completion_day()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF NEW.work_status='completed_in_tool' AND
 (NEW.work_status IS DISTINCT FROM OLD.work_status OR NEW.treatment_status IS DISTINCT FROM OLD.treatment_status OR NEW.completed_operational_day IS NULL)
 THEN NEW.completed_operational_day:=NEW.operational_day;
 ELSIF NEW.work_status<>'completed_in_tool' THEN NEW.completed_operational_day:=NULL;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sri_p03_completion_day ON public.daily_operator_tasks;
CREATE TRIGGER sri_p03_completion_day BEFORE UPDATE ON public.daily_operator_tasks
 FOR EACH ROW EXECUTE FUNCTION private.sri_p03_completion_day();

CREATE OR REPLACE FUNCTION private.sri_p03_roll_forward()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT NEW.active THEN RETURN NEW; END IF;
 IF EXISTS(
  SELECT 1 FROM public.daily_operator_tasks previous_task
  JOIN public.daily_result_snapshots old_snapshot ON old_snapshot.id=previous_task.snapshot_id
  JOIN public.daily_result_snapshots new_snapshot ON new_snapshot.id=NEW.snapshot_id
  WHERE previous_task.id<>NEW.id AND previous_task.protocol_number=NEW.protocol_number AND previous_task.active
  AND previous_task.operational_day<=NEW.operational_day
  AND old_snapshot.team_id IS NOT DISTINCT FROM new_snapshot.team_id
  AND NOT private.sri_p03_can_manage_task(previous_task.operator_user_id,previous_task.team_id)
 ) THEN RAISE EXCEPTION 'Atribuição anterior fora do escopo autorizado: revisão da gestão necessária'; END IF;
 UPDATE public.daily_operator_tasks previous_task SET active=false,updated_at=clock_timestamp()
 FROM public.daily_result_snapshots old_snapshot,public.daily_result_snapshots new_snapshot
 WHERE previous_task.snapshot_id=old_snapshot.id AND new_snapshot.id=NEW.snapshot_id
 AND previous_task.id<>NEW.id AND previous_task.protocol_number=NEW.protocol_number AND previous_task.active
 AND previous_task.operational_day<=NEW.operational_day
 AND old_snapshot.team_id IS NOT DISTINCT FROM new_snapshot.team_id
 AND private.sri_p03_can_manage_task(previous_task.operator_user_id,previous_task.team_id);
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION private.sri_p03_completion_day(),private.sri_p03_roll_forward() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS z_sri_p03_roll_forward ON public.daily_operator_tasks;
CREATE TRIGGER z_sri_p03_roll_forward AFTER INSERT ON public.daily_operator_tasks
 FOR EACH ROW EXECUTE FUNCTION private.sri_p03_roll_forward();

CREATE OR REPLACE FUNCTION private.sri_p03_preserve_open_tasks(
 p_snapshot uuid,p_day date,p_shift text,p_scope_team uuid,p_revision bigint)
RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE v_count integer:=0;
BEGIN
 IF EXISTS(
  SELECT 1 FROM public.daily_operator_tasks old
  JOIN public.daily_result_snapshots os ON os.id=old.snapshot_id
  JOIN public.daily_operator_tasks fresh ON fresh.snapshot_id=p_snapshot
       AND fresh.protocol_number=old.protocol_number
  WHERE old.snapshot_id<>p_snapshot AND old.active
   AND old.operational_day<=p_day
   AND os.team_id IS NOT DISTINCT FROM p_scope_team
   AND private.sri_p03_can_manage_task(old.operator_user_id,old.team_id)
   AND old.operator_user_id IS DISTINCT FROM fresh.operator_user_id
   AND (old.work_status<>'pending' OR EXISTS(
    SELECT 1 FROM public.daily_operator_treatments h WHERE h.task_id=old.id))
 ) THEN
  RAISE EXCEPTION 'Distribuição conflita com tratativa prévia: revisão manual obrigatória';
 END IF;
 WITH prior AS (
  SELECT DISTINCT ON(old.protocol_number) old.*
  FROM public.daily_operator_tasks old
  JOIN public.daily_result_snapshots os ON os.id=old.snapshot_id
  WHERE old.snapshot_id<>p_snapshot AND old.active
   AND old.operational_day<=p_day
   AND os.team_id IS NOT DISTINCT FROM p_scope_team
   AND private.sri_p03_can_manage_task(old.operator_user_id,old.team_id)
   AND old.work_status<>'completed_in_tool'
   AND private.sri_p03_status_sigo(old.treatment_status) IS DISTINCT FROM 3
   AND NOT EXISTS (SELECT 1 FROM public.daily_operator_tasks fresh
     WHERE fresh.snapshot_id=p_snapshot AND fresh.protocol_number=old.protocol_number)
  ORDER BY old.protocol_number,old.updated_at DESC,old.id DESC
 )
 INSERT INTO public.daily_operator_tasks
  (snapshot_id,team_id,operational_day,shift_label,protocol_number,operator_user_id,
   criticality,due_situation,sla_band,channel,source_status,work_status,
   treatment_status,active,distribution_revision,priority_reason,due_date,base_name,area_name)
 SELECT p_snapshot,old.team_id,p_day,p_shift,old.protocol_number,old.operator_user_id,
  old.criticality,old.due_situation,old.sla_band,old.channel,old.source_status,
  old.work_status,old.treatment_status,true,p_revision,old.priority_reason,old.due_date,
  old.base_name,old.area_name
 FROM prior old JOIN public.profiles op ON op.id=old.operator_user_id
  AND op.role='operator' AND op.operational_status IN ('Ativo','Promovido')
 ON CONFLICT(snapshot_id,protocol_number) DO NOTHING;
 GET DIAGNOSTICS v_count=ROW_COUNT;
 UPDATE public.daily_operator_tasks t SET distribution_revision=p_revision,updated_at=now()
 WHERE t.snapshot_id=p_snapshot AND t.active AND t.distribution_revision<>p_revision
   AND private.sri_p03_can_manage_task(t.operator_user_id,t.team_id)
   AND t.work_status<>'completed_in_tool'
   AND private.sri_p03_status_sigo(t.treatment_status) IS DISTINCT FROM 3;
 IF v_count>0 THEN
  INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
  VALUES(auth.uid(),'P03_UNFINISHED_CARRIED','daily_result',p_snapshot::text,
    jsonb_build_object('day',p_day,'shift',p_shift,'carried',v_count,'revision',p_revision));
 END IF;
 RETURN v_count;
END $$;
REVOKE ALL ON FUNCTION private.sri_p03_preserve_open_tasks(uuid,date,text,uuid,bigint) FROM PUBLIC,anon,authenticated;


-- Repeated publication must preserve the active flag derived by the carry trigger.
DO $publication_active$
DECLARE routine regprocedure; definition text;
BEGIN
 FOREACH routine IN ARRAY ARRAY['public.publish_daily_operator_tasks(uuid,bigint,jsonb)'::regprocedure,
  'public.publish_general_operator_tasks(uuid,bigint,jsonb)'::regprocedure] LOOP
  definition:=pg_get_functiondef(routine);
  definition:=replace(definition,'active=true,distribution_revision=EXCLUDED.distribution_revision',
   'active=EXCLUDED.active,distribution_revision=EXCLUDED.distribution_revision');
  EXECUTE definition;
 END LOOP;
END $publication_active$;

-- SOURCE sql/2026-11-25_sri_p03_auditoria_contexto.sql
CREATE INDEX IF NOT EXISTS sri_p03_treatment_task_actor ON public.daily_operator_treatments(task_id,actor_id);
CREATE INDEX IF NOT EXISTS sri_p03_task_productivity_date ON public.daily_operator_tasks(operational_day,team_id,operator_user_id,protocol_number);
CREATE INDEX IF NOT EXISTS sri_p03_treatment_actor_date ON public.daily_operator_treatments(actor_id,created_at,id DESC);
CREATE INDEX IF NOT EXISTS sri_p03_audit_object_page ON public.audit_events(object_type,object_id,id DESC);

CREATE OR REPLACE FUNCTION private.sri_p03_audit_context()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE task public.daily_operator_tasks%rowtype; actor_name text; actor_role text;
BEGIN
 IF jsonb_typeof(NEW.details) IS DISTINCT FROM 'object' THEN
  NEW.details:=CASE WHEN NEW.details IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('original_details',NEW.details) END;
 END IF;
 SELECT full_name,role INTO actor_name,actor_role FROM public.profiles WHERE id=NEW.user_id;
 NEW.details:=NEW.details||jsonb_build_object('actor_name_at_event',actor_name,'actor_role_at_event',actor_role,
  'event_origin',CASE WHEN NEW.user_id IS NULL THEN 'database' ELSE 'user' END);
 IF NEW.object_type='daily_operator_task' THEN
  SELECT * INTO task FROM public.daily_operator_tasks WHERE id=CASE WHEN NEW.object_id ~ '^[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$' THEN NEW.object_id::uuid END;
  IF FOUND THEN
   NEW.details:=NEW.details||jsonb_build_object('event_protocol',task.protocol_number,'event_base',task.base_name,
    'event_area',task.area_name,'event_team_id',task.team_id,'event_snapshot_id',task.snapshot_id,
    'event_operator_id',task.operator_user_id,'event_operator_name',(SELECT full_name FROM public.profiles WHERE id=task.operator_user_id),
    'event_team_name',(SELECT name FROM public.teams WHERE id=task.team_id));
  END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sri_p03_audit_context ON public.audit_events;
CREATE TRIGGER sri_p03_audit_context BEFORE INSERT ON public.audit_events
 FOR EACH ROW EXECUTE FUNCTION private.sri_p03_audit_context();

CREATE OR REPLACE FUNCTION private.sri_p03_task_movement()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE action_name text; previous_value jsonb; next_value jsonb;
BEGIN
 IF TG_OP='INSERT' THEN
  action_name:=CASE WHEN NEW.carried_from_task_id IS NULL THEN 'TASK_ASSIGNED' ELSE 'TASK_CARRIED' END;
  next_value:=jsonb_build_object('operator',NEW.operator_user_id,'team',NEW.team_id,'active',NEW.active,'carried_from',NEW.carried_from_task_id);
 ELSIF NEW.operator_user_id IS DISTINCT FROM OLD.operator_user_id OR NEW.team_id IS DISTINCT FROM OLD.team_id THEN
  action_name:='TASK_REASSIGNED';
  previous_value:=jsonb_build_object('operator',OLD.operator_user_id,'team',OLD.team_id);
  next_value:=jsonb_build_object('operator',NEW.operator_user_id,'team',NEW.team_id);
 ELSIF NEW.active IS DISTINCT FROM OLD.active THEN
  action_name:=CASE WHEN NEW.active THEN 'TASK_ACTIVATED' ELSE 'TASK_ARCHIVED' END;
  previous_value:=to_jsonb(OLD.active);next_value:=to_jsonb(NEW.active);
 ELSE
  previous_value:=jsonb_build_object('base',OLD.base_name,'area',OLD.area_name,'source',OLD.source_status,'criticality',OLD.criticality,'due_date',OLD.due_date);
  next_value:=jsonb_build_object('base',NEW.base_name,'area',NEW.area_name,'source',NEW.source_status,'criticality',NEW.criticality,'due_date',NEW.due_date);
  IF previous_value IS NOT DISTINCT FROM next_value THEN RETURN NEW; END IF;
  action_name:='TASK_METADATA_CHANGED';
 END IF;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES(auth.uid(),action_name,'daily_operator_task',NEW.id::text,
  jsonb_build_object('previous_value',previous_value,'new_value',next_value));
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS sri_p03_task_movement ON public.daily_operator_tasks;
CREATE TRIGGER sri_p03_task_movement AFTER INSERT OR UPDATE ON public.daily_operator_tasks
 FOR EACH ROW EXECUTE FUNCTION private.sri_p03_task_movement();

CREATE OR REPLACE FUNCTION private.sri_movement_read(p_from timestamptz,p_to timestamptz,p_protocol text,p_before bigint DEFAULT NULL)
RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE role_name text;
BEGIN
 SELECT role INTO role_name FROM public.profiles WHERE id=auth.uid();
 IF role_name IS NULL OR role_name NOT IN ('admin','manager','supervisor','assistant') THEN RAISE EXCEPTION 'Acesso restrito à gestão'; END IF;
 IF p_from IS NULL OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>interval '367 days' THEN RAISE EXCEPTION 'Período inválido'; END IF;
 RETURN QUERY
 SELECT jsonb_build_object('id',e.id::text,'occurred_at',e.occurred_at,'action',e.action,
 'protocol',coalesce(e.details->>'event_protocol',task.protocol_number),
 'base',e.details->>'event_base','area',e.details->>'event_area',
 'responsavel',coalesce(e.details->>'actor_name_at_event',actor.full_name,'Banco de dados / autoria não informada'),
 'perfil',coalesce(e.details->>'actor_role_at_event','Não registrado'),
 'origin',coalesce(e.details->>'event_origin','Não registrado'),'justificativa',coalesce(e.details->>'reason',e.details->>'justification'),
 'anterior',coalesce(e.details->>'previous_treatment_status',e.details->>'previous_value'),
 'novo',coalesce(e.details->>'treatment_status',e.details->>'new_value'),'object_type',e.object_type)
 FROM public.audit_events e
 LEFT JOIN public.daily_operator_tasks task ON e.object_type='daily_operator_task' AND e.object_id=task.id::text
 LEFT JOIN public.profiles actor ON actor.id=e.user_id
 WHERE e.occurred_at>=p_from AND e.occurred_at<p_to AND (p_before IS NULL OR e.id<p_before)
 AND (p_protocol IS NULL OR coalesce(e.details->>'event_protocol',task.protocol_number)=p_protocol)
 AND (role_name IN ('admin','manager') OR private.is_supervisor_of(
  coalesce((e.details->>'event_team_id')::uuid,task.team_id)))
 ORDER BY e.id DESC LIMIT 200;
END $$;
REVOKE ALL ON FUNCTION private.sri_p03_audit_context(),private.sri_p03_task_movement() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION private.sri_movement_read(timestamptz,timestamptz,text,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.sri_movement_read(timestamptz,timestamptz,text,bigint) TO authenticated;

-- SOURCE sql/2026-11-25_sri_p03_escopo_apuracao_geral.sql
CREATE OR REPLACE FUNCTION private.sri_p03_distribution_is_scoped(p_state jsonb)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE reference text; actor_role text; operator_id uuid; operator_team uuid;
BEGIN
 IF private.is_manager() THEN RETURN true; END IF;
 SELECT role INTO actor_role FROM public.profiles WHERE id=auth.uid();
 IF actor_role IS NULL OR actor_role NOT IN ('supervisor','assistant') OR jsonb_typeof(p_state) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 IF jsonb_typeof(coalesce(p_state->'assignments','{}'::jsonb))<>'object'
 OR jsonb_typeof(coalesce(p_state->'roster','[]'::jsonb))<>'array'
 OR jsonb_typeof(coalesce(p_state->'archivedRoster','[]'::jsonb))<>'array' THEN RETURN false; END IF;
 FOR reference IN
  SELECT DISTINCT value FROM (
   SELECT value->>'opId' value FROM jsonb_each(coalesce(p_state->'assignments','{}'::jsonb))
   UNION ALL SELECT value->>'id' FROM jsonb_array_elements(coalesce(p_state->'roster','[]'::jsonb))
   UNION ALL SELECT value->>'id' FROM jsonb_array_elements(coalesce(p_state->'archivedRoster','[]'::jsonb))
  ) refs
 LOOP
  IF reference IS NULL OR reference !~ '^acct:[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$' THEN RETURN false; END IF;
  operator_id:=substring(reference FROM 6)::uuid;
  SELECT member.team_id INTO operator_team FROM public.team_memberships member WHERE member.user_id=operator_id
  AND private.is_supervisor_of(member.team_id) LIMIT 1;
  IF NOT private.sri_p03_can_manage_task(operator_id,operator_team) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION private.sri_p03_distribution_is_scoped(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.sri_p03_distribution_is_scoped(jsonb) TO authenticated;

