CREATE OR REPLACE FUNCTION private.sri_p03_guard_completed_change()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF (OLD.work_status='completed_in_tool' OR private.sri_p03_status_sigo(OLD.treatment_status)=3)
 AND (NEW.work_status IS DISTINCT FROM OLD.work_status OR NEW.treatment_status IS DISTINCT FROM OLD.treatment_status) THEN
  DELETE FROM private.sri_p03_reopen_permits WHERE task_id=OLD.id AND actor_id=auth.uid() AND transaction_id=txid_current();
  IF NOT FOUND THEN RAISE EXCEPTION 'Protocolo concluído. Somente Administrador/Gestor pode reabrir com justificativa'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION private.sri_p03_guard_completed_treatment()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE task public.daily_operator_tasks%rowtype;
BEGIN
 SELECT * INTO task FROM public.daily_operator_tasks WHERE id=NEW.task_id FOR UPDATE;
 IF task.work_status='completed_in_tool' OR private.sri_p03_status_sigo(task.treatment_status)=3 THEN
  RAISE EXCEPTION 'Protocolo concluído. Solicite reabertura justificada ao Administrador/Gestor';
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION private.sri_p03_guard_completed_change(),private.sri_p03_guard_completed_treatment() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS sri_p03_guard_completed_change ON public.daily_operator_tasks;
CREATE TRIGGER sri_p03_guard_completed_change BEFORE UPDATE OF work_status,treatment_status ON public.daily_operator_tasks FOR EACH ROW EXECUTE FUNCTION private.sri_p03_guard_completed_change();
DROP TRIGGER IF EXISTS sri_p03_guard_completed_treatment ON public.daily_operator_treatments;
CREATE TRIGGER sri_p03_guard_completed_treatment BEFORE INSERT ON public.daily_operator_treatments FOR EACH ROW EXECUTE FUNCTION private.sri_p03_guard_completed_treatment();

-- SOURCE sql/2026-11-25_sri_p03_relatorios_integrados.sql
-- Preserve context at the instant of the treatment. No historical backfill.
CREATE OR REPLACE FUNCTION private.sri_p03_capture_treatment_context()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 SELECT jsonb_build_object('protocol_number',t.protocol_number,'base_name',t.base_name,'area_name',t.area_name,
  'source_status',t.source_status,'work_status',private.sri_p03_status_work(NEW.action),'version','20261125',
  'team_id',t.team_id,'team_name',tm.name,'actor_name',p.full_name,'criticality',t.criticality,
  'sla_band',t.sla_band,'due_situation',t.due_situation,'due_date',t.due_date,'channel',t.channel)
 INTO NEW.event_context FROM public.daily_operator_tasks t
 LEFT JOIN public.teams tm ON tm.id=t.team_id LEFT JOIN public.profiles p ON p.id=NEW.actor_id WHERE t.id=NEW.task_id;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION private.sri_p03_reporting_page(p_from date,p_to date,p_after text DEFAULT NULL)
RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE viewer_role text; start_at timestamptz; end_at timestamptz;
BEGIN
 SELECT role INTO viewer_role FROM public.profiles WHERE id=auth.uid();
 IF viewer_role IS NULL OR viewer_role NOT IN ('admin','manager','supervisor','assistant') THEN RAISE EXCEPTION 'Relatórios restritos à gestão'; END IF;
 IF p_from IS NULL OR p_to IS NULL OR p_to<p_from OR p_to-p_from>92 THEN RAISE EXCEPTION 'Selecione até 93 dias'; END IF;
 start_at:=p_from::timestamp AT TIME ZONE 'America/Sao_Paulo';end_at:=(p_to+1)::timestamp AT TIME ZONE 'America/Sao_Paulo';
 RETURN QUERY
 WITH scoped_tasks AS MATERIALIZED (
  SELECT t.*,tm.name AS team_name,p.full_name AS operator_name FROM public.daily_operator_tasks t
  LEFT JOIN public.teams tm ON tm.id=t.team_id LEFT JOIN public.profiles p ON p.id=t.operator_user_id
  WHERE (viewer_role IN ('admin','manager') OR (t.team_id IS NOT NULL AND private.is_supervisor_of(t.team_id)))
 ), events AS (
  SELECT 'A:'||t.id::text AS cursor_key,jsonb_build_object('kind','assignment','id',t.id,'day',t.operational_day,
   'at',t.created_at,'protocol',t.protocol_number,'team_id',t.team_id,'team',t.team_name,'operator_id',t.operator_user_id,
   'operator',t.operator_name,'base',t.base_name,'area',t.area_name,'sla',t.sla_band,'criticality',t.criticality,
   'due_situation',t.due_situation,'due_date',t.due_date,'channel',t.channel,'source_status',t.source_status,
   'work_status',t.work_status,'status',t.treatment_status,'active',t.active,
   'state_reference','Estado armazenado da atribuição; conclusões do período são calculadas pelos eventos') AS payload
  FROM scoped_tasks t WHERE t.operational_day BETWEEN p_from AND p_to
  UNION ALL
  SELECT 'H:'||lpad(h.id::text,20,'0'),jsonb_build_object('kind','treatment','id',h.id::text,
   'day',(h.created_at AT TIME ZONE 'America/Sao_Paulo')::date,'at',h.created_at,'protocol',coalesce(h.event_context->>'protocol_number',t.protocol_number),
   'team_id',coalesce((h.event_context->>'team_id')::uuid,t.team_id),'team',coalesce(h.event_context->>'team_name',t.team_name),
   'operator_id',h.actor_id,'operator',coalesce(h.event_context->>'actor_name',p.full_name),
   'base',h.event_context->>'base_name','area',h.event_context->>'area_name','status',h.action,
   'sla',h.event_context->>'sla_band','criticality',h.event_context->>'criticality','context_available',h.event_context IS NOT NULL)
  FROM public.daily_operator_treatments h JOIN scoped_tasks t ON t.id=h.task_id LEFT JOIN public.profiles p ON p.id=h.actor_id
  WHERE h.created_at>=start_at AND h.created_at<end_at
   AND (viewer_role IN ('admin','manager') OR private.is_supervisor_of(coalesce((h.event_context->>'team_id')::uuid,t.team_id)))
  UNION ALL
  SELECT 'I:'||s.id::text,jsonb_build_object('kind','import','id',s.id,'day',s.operational_day,'at',s.created_at,
   'team_id',s.team_id,'team',tm.name,'operator_id',s.imported_by,'operator',p.full_name,'shift',s.shift_label,
   'protocol_count',s.protocol_count,'indicators',s.indicators)
  FROM public.daily_result_snapshots s LEFT JOIN public.teams tm ON tm.id=s.team_id LEFT JOIN public.profiles p ON p.id=s.imported_by
  WHERE s.operational_day BETWEEN p_from AND p_to AND (viewer_role IN ('admin','manager') OR
   (s.team_id IS NOT NULL AND private.is_supervisor_of(s.team_id)) OR (s.team_id IS NULL AND s.imported_by=auth.uid()))
  UNION ALL
  SELECT 'R:'||lpad(r.id::text,20,'0'),jsonb_build_object('kind','reconciliation','id',r.id::text,
   'day',(r.observed_at AT TIME ZONE 'America/Sao_Paulo')::date,'at',r.observed_at,'protocol',r.protocol_number,
   'team_id',r.team_id,'team',tm.name,'operator_id',r.operator_id,'operator',p.full_name,'base',r.base_name,'area',r.area_name,
   'previous',r.previous_source,'source_status',r.current_source,'status',r.manual_status,'decision',r.decision,
   'decision_at',r.decided_at,'justification',r.justification,'event_kind',r.event_kind)
  FROM private.sri_status_reconciliation r LEFT JOIN public.teams tm ON tm.id=r.team_id LEFT JOIN public.profiles p ON p.id=r.operator_id
  WHERE r.observed_at>=start_at AND r.observed_at<end_at AND (viewer_role IN ('admin','manager') OR
   (r.team_id IS NOT NULL AND private.is_supervisor_of(r.team_id)))
  UNION ALL
  SELECT 'C:team:'||c.id::text,jsonb_build_object('kind','closure','id','team:'||c.id::text,
   'day',c.operational_day,'at',c.closed_at,'team_id',c.team_id,'team',tm.name,'shift',c.shift_label,
   'status',c.status,'reopened_at',c.reopened_at,'justification',c.reopen_reason)
  FROM public.sri_result_shift_closures c LEFT JOIN public.teams tm ON tm.id=c.team_id
  WHERE c.operational_day BETWEEN p_from AND p_to AND (viewer_role IN ('admin','manager') OR private.is_supervisor_of(c.team_id))
  UNION ALL
  SELECT 'C:general:'||c.operational_day::text,jsonb_build_object('kind','closure','id','general:'||c.operational_day::text,
   'day',c.operational_day,'at',c.closed_at,'status',c.status,'protocol_count',c.protocol_count,'scope','general')
  FROM public.sri_general_day_closures c WHERE c.operational_day BETWEEN p_from AND p_to AND viewer_role IN ('admin','manager')
  UNION ALL
  SELECT 'V:'||lpad(e.id::text,20,'0'),jsonb_build_object('kind','movement','id',e.id::text,
   'day',(e.occurred_at AT TIME ZONE 'America/Sao_Paulo')::date,'at',e.occurred_at,
   'protocol',coalesce(e.details->>'event_protocol',t.protocol_number),'team_id',coalesce((e.details->>'event_team_id')::uuid,t.team_id),
   'team',coalesce(e.details->>'event_team_name',tm.name),'assigned_operator_id',coalesce(e.details->>'event_operator_id',t.operator_user_id::text),
   'assigned_operator',coalesce(e.details->>'event_operator_name',t.operator_name),'operator_id',e.user_id,'operator',coalesce(e.details->>'actor_name_at_event',p.full_name),
   'base',e.details->>'event_base','area',e.details->>'event_area','action',e.action,
   'previous',coalesce(e.details->>'previous_treatment_status',e.details->>'previous_value'),
   'status',coalesce(e.details->>'treatment_status',e.details->>'new_value'),
   'justification',coalesce(e.details->>'reason',e.details->>'justification'),'origin',e.details->>'event_origin')
  FROM public.audit_events e LEFT JOIN scoped_tasks t ON e.object_type='daily_operator_task' AND e.object_id=t.id::text
  LEFT JOIN public.teams tm ON tm.id=coalesce((e.details->>'event_team_id')::uuid,t.team_id) LEFT JOIN public.profiles p ON p.id=e.user_id
  WHERE e.occurred_at>=start_at AND e.occurred_at<end_at AND (viewer_role IN ('admin','manager') OR
   private.is_supervisor_of(coalesce((e.details->>'event_team_id')::uuid,t.team_id)))
 )
 SELECT payload||jsonb_build_object('cursor',cursor_key) FROM events
 WHERE p_after IS NULL OR cursor_key>p_after ORDER BY cursor_key LIMIT 400;
END $$;
CREATE OR REPLACE FUNCTION public.sri_p03_reporting_page(p_from date,p_to date,p_after text DEFAULT NULL)
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT * FROM private.sri_p03_reporting_page(p_from,p_to,p_after)
$$;
REVOKE ALL ON FUNCTION private.sri_p03_reporting_page(date,date,text),public.sri_p03_reporting_page(date,date,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.sri_p03_reporting_page(date,date,text),public.sri_p03_reporting_page(date,date,text) TO authenticated;

-- SOURCE sql/2026-11-25_sri_p03_meta_conclusao.sql
CREATE TABLE IF NOT EXISTS private.sri_p03_completion_goals (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 scope text NOT NULL CHECK(scope IN ('general','team','operator')),
 target uuid,
 effective date NOT NULL,
 percentage numeric(5,2) NOT NULL CHECK(percentage BETWEEN 0 AND 100),
 created_at timestamptz NOT NULL DEFAULT now(),
 created_by uuid NOT NULL REFERENCES public.profiles(id),
 CHECK((scope='general' AND target IS NULL) OR (scope<>'general' AND target IS NOT NULL))
);
ALTER TABLE private.sri_p03_completion_goals ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.sri_p03_completion_goals FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS sri_p03_goal_version ON private.sri_p03_completion_goals(scope,target,effective DESC,id DESC);
CREATE OR REPLACE FUNCTION private.sri_p03_goal_allowed(p_scope text,p_target uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.profiles viewer WHERE viewer.id=auth.uid() AND
  (viewer.role IN ('admin','manager') OR (viewer.role IN ('supervisor','assistant') AND
   ((p_scope='team' AND private.is_supervisor_of(p_target)) OR (p_scope='operator' AND EXISTS(
    SELECT 1 FROM public.team_memberships m WHERE m.user_id=p_target AND private.is_supervisor_of(m.team_id)))))))
$$;
CREATE OR REPLACE FUNCTION private.sri_p03_goals()
RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role IN ('admin','manager','supervisor','assistant')) THEN RAISE EXCEPTION 'Acesso restrito à gestão'; END IF;
 RETURN QUERY SELECT jsonb_build_object('id',g.id::text,'scope',g.scope,'target',g.target,'effective',g.effective,
  'percentage',g.percentage,'created_at',g.created_at,'created_by',g.created_by,
  'target_name',CASE WHEN g.scope='general' THEN 'Toda a operação' WHEN g.scope='team' THEN tm.name ELSE p.full_name END)
 FROM private.sri_p03_completion_goals g LEFT JOIN public.teams tm ON g.scope='team' AND tm.id=g.target
 LEFT JOIN public.profiles p ON g.scope='operator' AND p.id=g.target
 WHERE g.scope='general' OR private.sri_p03_goal_allowed(g.scope,g.target)
 ORDER BY g.effective DESC,g.id DESC;
END $$;
CREATE OR REPLACE FUNCTION private.sri_p03_goal_save(p_scope text,p_target uuid,p_effective date,p_percentage numeric,p_expected bigint DEFAULT NULL)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE current_id bigint; new_id bigint;
BEGIN
 IF NOT private.sri_p03_goal_allowed(p_scope,p_target) THEN RAISE EXCEPTION 'Meta fora do escopo autorizado'; END IF;
 IF p_scope NOT IN ('general','team','operator') OR p_effective IS NULL OR p_percentage IS NULL OR p_percentage<0 OR p_percentage>100
 OR (p_scope='general' AND p_target IS NOT NULL) OR (p_scope<>'general' AND p_target IS NULL) THEN RAISE EXCEPTION 'Parâmetros da meta inválidos'; END IF;
 IF p_scope='team' AND NOT EXISTS(SELECT 1 FROM public.teams WHERE id=p_target AND active) THEN RAISE EXCEPTION 'Equipe inválida'; END IF;
 IF p_scope='operator' AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_target AND role='operator' AND operational_status IN ('Ativo','Promovido')) THEN RAISE EXCEPTION 'Operador inválido'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-goal:'||p_scope||':'||coalesce(p_target::text,'general')||':'||p_effective::text,0));
 SELECT id INTO current_id FROM private.sri_p03_completion_goals WHERE scope=p_scope AND target IS NOT DISTINCT FROM p_target AND effective=p_effective ORDER BY id DESC LIMIT 1;
 IF current_id IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'Meta atualizada por outro usuário. Consulte novamente'; END IF;
 INSERT INTO private.sri_p03_completion_goals(scope,target,effective,percentage,created_by)
 VALUES(p_scope,p_target,p_effective,p_percentage,auth.uid()) RETURNING id INTO new_id;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES(auth.uid(),'COMPLETION_GOAL_VERSION','completion_goal',new_id::text,
  jsonb_build_object('scope',p_scope,'target',p_target,'effective',p_effective,'percentage',p_percentage,'previous_version',current_id));
 RETURN new_id;
END $$;
CREATE OR REPLACE FUNCTION public.sri_p03_goals() RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT * FROM private.sri_p03_goals() $$;
CREATE OR REPLACE FUNCTION public.sri_p03_goal_save(p_scope text,p_target uuid,p_effective date,p_percentage numeric,p_expected bigint DEFAULT NULL)
RETURNS bigint LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT private.sri_p03_goal_save(p_scope,p_target,p_effective,p_percentage,p_expected) $$;
REVOKE ALL ON FUNCTION private.sri_p03_goal_allowed(text,uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION private.sri_p03_goals(),public.sri_p03_goals(),private.sri_p03_goal_save(text,uuid,date,numeric,bigint),public.sri_p03_goal_save(text,uuid,date,numeric,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.sri_p03_goals(),public.sri_p03_goals(),private.sri_p03_goal_save(text,uuid,date,numeric,bigint),public.sri_p03_goal_save(text,uuid,date,numeric,bigint) TO authenticated;

-- SOURCE sql/2026-11-25_sri_p03_vinculo_auditoria_monitor.sql
ALTER TABLE private.sri_p03_monitor_occurrences ADD COLUMN IF NOT EXISTS error_code text, ADD COLUMN IF NOT EXISTS http_status integer;
CREATE TABLE IF NOT EXISTS private.sri_p03_monitor_audit_links(
 occurrence_id bigint PRIMARY KEY REFERENCES private.sri_p03_monitor_occurrences(id) ON DELETE RESTRICT,
 event_id bigint NOT NULL REFERENCES private.sri_monitor_events(id) ON DELETE RESTRICT,
 audit_id bigint NOT NULL REFERENCES public.audit_events(id) ON DELETE RESTRICT
);
ALTER TABLE private.sri_p03_monitor_audit_links ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.sri_p03_monitor_audit_links FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS sri_p03_monitor_link_event ON private.sri_p03_monitor_audit_links(event_id,occurrence_id);
CREATE OR REPLACE FUNCTION private.sri_p03_monitor_audit()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE previous_id bigint; occurrence_key bigint; event_key bigint;
BEGIN
 IF auth.uid() IS NULL OR NEW.user_id IS DISTINCT FROM auth.uid() OR NEW.action NOT IN
 ('DAY_TASK_TREATMENT','TASK_REOPENED','COMPLETION_GOAL_VERSION','STATUS_RECONCILIATION','RECONCILIATION_DECISION') THEN RETURN NEW; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.user_id) THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-monitor:'||NEW.user_id::text,0));
 SELECT max(id) INTO previous_id FROM private.sri_p03_monitor_occurrences WHERE actor_id=NEW.user_id;
 PERFORM private.sri_monitor_write('INFO','OPERATION_AUDIT','Carteira','pacote03-20261124');
 SELECT id,event_id INTO occurrence_key,event_key FROM private.sri_p03_monitor_occurrences
 WHERE actor_id=NEW.user_id AND id>coalesce(previous_id,0) ORDER BY id DESC LIMIT 1;
 IF occurrence_key IS NOT NULL THEN
  INSERT INTO private.sri_p03_monitor_audit_links(occurrence_id,event_id,audit_id) VALUES(occurrence_key,event_key,NEW.id);
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION private.sri_p03_monitor_audit() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS sri_p03_monitor_audit ON public.audit_events;
CREATE TRIGGER sri_p03_monitor_audit AFTER INSERT ON public.audit_events FOR EACH ROW EXECUTE FUNCTION private.sri_p03_monitor_audit();
CREATE OR REPLACE FUNCTION private.sri_p03_monitor_occurrences(p_event bigint,p_before bigint DEFAULT NULL)
RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role='admin') THEN RAISE EXCEPTION 'Acesso exclusivo ao administrador'; END IF;
 RETURN QUERY SELECT jsonb_build_object('id',o.id::text,'event_id',o.event_id::text,'occurred_at',o.occurred_at,
  'error_code',o.error_code,'http_status',o.http_status,'audit_id',a.id::text,'audit_at',a.occurred_at,'protocol',a.details->>'event_protocol','action',a.action)
 FROM private.sri_p03_monitor_occurrences o LEFT JOIN private.sri_p03_monitor_audit_links l ON l.occurrence_id=o.id
 LEFT JOIN public.audit_events a ON a.id=l.audit_id WHERE o.event_id=p_event AND (p_before IS NULL OR o.id<p_before)
 ORDER BY o.id DESC LIMIT 200;
END $$;

CREATE OR REPLACE FUNCTION private.sri_p03_monitor_error(p_rpc boolean,p_error_code text,p_http_status integer)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE previous_id bigint; safe_code text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid()) THEN RAISE EXCEPTION 'Sessão obrigatória'; END IF;
 safe_code:=CASE WHEN p_error_code ~ '^[A-Z0-9]{5,10}$' THEN p_error_code END;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-monitor:'||auth.uid()::text,0));
 SELECT max(id) INTO previous_id FROM private.sri_p03_monitor_occurrences WHERE actor_id=auth.uid();
 PERFORM private.sri_monitor_write('ERROR',CASE WHEN p_rpc THEN 'RPC_ERROR' ELSE 'REST_ERROR' END,'Supabase','pacote03-20261124');
 UPDATE private.sri_p03_monitor_occurrences SET error_code=safe_code,
 http_status=CASE WHEN p_http_status BETWEEN 400 AND 599 THEN p_http_status END
 WHERE actor_id=auth.uid() AND id>coalesce(previous_id,0);
END $$;
CREATE OR REPLACE FUNCTION public.sri_p03_monitor_error(p_rpc boolean,p_error_code text,p_http_status integer)
RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT private.sri_p03_monitor_error(p_rpc,p_error_code,p_http_status) $$;
REVOKE ALL ON FUNCTION private.sri_p03_monitor_error(boolean,text,integer),public.sri_p03_monitor_error(boolean,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.sri_p03_monitor_error(boolean,text,integer),public.sri_p03_monitor_error(boolean,text,integer) TO authenticated;
CREATE OR REPLACE FUNCTION private.sri_monitor_read(p_from timestamptz,p_to timestamptz,p_level text,p_before bigint DEFAULT NULL)
RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role='admin') THEN RAISE EXCEPTION 'Acesso exclusivo ao administrador'; END IF;
 IF p_from IS NULL OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>interval '367 days' THEN RAISE EXCEPTION 'Período inválido'; END IF;
 RETURN QUERY SELECT jsonb_build_object('id',e.id::text,'occurred_at',e.occurred_at,'last_at',e.last_at,
 'severity',e.severity,'code',e.code,'module',e.module,'version',e.version,'occurrences',e.occurrences,'responsavel',p.full_name,
 'technical_codes',(SELECT string_agg(DISTINCT o.error_code,', ' ORDER BY o.error_code) FROM private.sri_p03_monitor_occurrences o WHERE o.event_id=e.id))
 FROM private.sri_monitor_events e LEFT JOIN public.profiles p ON p.id=e.actor_id
 WHERE e.occurred_at>=p_from AND e.occurred_at<p_to AND (p_level IS NULL OR e.severity=p_level)
 AND (p_before IS NULL OR e.id<p_before) ORDER BY e.id DESC LIMIT 200;
END $$;

DO $integrity_after$
DECLARE item record; total bigint; digest text;
BEGIN
 FOR item IN SELECT * FROM sri_p03_preflight_integrity LOOP
  EXECUTE 'SELECT count(*),md5(coalesce(jsonb_agg(original ORDER BY original::text)::text,''[]'')) FROM (SELECT (SELECT jsonb_object_agg(key,value) FROM jsonb_each(to_jsonb(t)) WHERE key=ANY($1)) original FROM '||item.relation_name||' t) rows'
  INTO total,digest USING item.original_columns;
  IF total IS DISTINCT FROM item.row_count OR digest IS DISTINCT FROM item.content_hash THEN
   RAISE EXCEPTION 'Integrity check failed for %. Transaction rolled back.',item.relation_name;
  END IF;
 END LOOP;
END $integrity_after$;
COMMIT;
